const APP = { name: "Depotbestand", version: "3.31", file: "depotbestand.json" };
const COMDIRECT_API_BASE = "https://api.comdirect.de";
const COMDIRECT_KEYCHAIN_KEY = APP.name + ".comdirect-credentials";

/* ---------------------------------------------------------------------------
 * Hilfsfunktionen
 * -------------------------------------------------------------------------*/

function toNumber(v) {
  if (v === null || v === undefined || v === "") return null;
  if (typeof v === "number") return Number.isFinite(v) ? v : null;
  let str = String(v).trim().replace(/[\s€]/g, "");
  if (str === "") return null;
  // Deutsche Eingabe "1.234,56" → 1234.56; API-Werte ("1234.56") bleiben unverändert.
  if (str.indexOf(",") >= 0) str = str.replace(/\./g, "").replace(",", ".");
  const n = Number(str);
  return Number.isFinite(n) ? n : null;
}
function validNumber(n) { return typeof n === "number" && Number.isFinite(n); }
/* Benutzereingabe (deutsch): wie toNumber, aber „2.500“ / „1.234.567“ (nur Punkte in Dreiergruppen,
 * kein Komma) sind Tausenderpunkte → 2500 bzw. 1234567. toNumber selbst bleibt für API-Werte
 * („1.234“ = 1,234) unverändert. */
function userNumber(v) {
  if (typeof v === "string") {
    const t = v.trim().replace(/[\s€]/g, "").replace(/^−/, "-");
    if (/^[+-]?\d{1,3}(\.\d{3})+$/.test(t)) return toNumber(t.replace(/\./g, ""));
  }
  return toNumber(v);
}


/* Stückzahl: ganze Zahlen ohne, Bruchstücke (Sparpläne) mit bis zu 4 Nachkommastellen. */
function fmtQty(n) {
  if (!validNumber(n)) return "–";
  return n.toLocaleString("de-DE", { minimumFractionDigits: 0, maximumFractionDigits: 4 });
}

/* Yahoo liefert manche Börsen in der Untereinheit (GBp = Pence, ZAc = Cent, ILA = Agorot).
 * Vor der EUR-Umrechnung auf die Haupteinheit (/100) bringen — sonst 100-fach zu hoch. */
function normalizeQuoteUnit(price, currency) {
  const c = String(currency || "").trim();
  const minor = { GBp: "GBP", GBX: "GBP", ZAc: "ZAR", ILA: "ILS" };
  if (minor[c]) return { price: validNumber(price) ? price / 100 : price, currency: minor[c], scaled: true };
  return { price: price, currency: c.toUpperCase(), scaled: false };
}
/* Skaliert eine {t,c}-Reihe in-place, falls Yahoo sie in der Untereinheit liefert; gibt die Haupt-Währung zurück. */
function applyMinorUnitScale(points, meta) {
  const n = normalizeQuoteUnit(1, meta && meta.currency);
  if (n.scaled) points.forEach(function (x) { x.c = x.c / 100; });
  return n.currency;
}

function fmtEur(n) {
  if (!validNumber(n)) return "–";
  return n.toLocaleString("de-DE", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " €";
}
/* Euro mit Vorzeichen (+/−) für G/V-Werte. */
function fmtEurSigned(n) {
  if (!validNumber(n)) return "–";
  const r = Math.round(n * 100) / 100;
  return (r > 0 ? "+" : (r < 0 ? "−" : "")) + fmtEur(Math.abs(r));
}
/* Richtungspfeil vor G/V, damit Gewinn/Verlust nicht nur über die Farbe erkennbar ist. */
function gvArrow(n) {
  if (!validNumber(n) || Math.round(n * 100) === 0) return "";
  return "<span class=\"gvar\">" + (n > 0 ? "▲" : "▼") + "</span>";
}
/* Arbeitet items mit höchstens `limit` gleichzeitigen Abrufen ab. Anders als feste
 * 4er-Blöcke wartet ein freier Platz nicht auf den langsamsten Abruf des Blocks.
 * worker(item, index) darf werfen; Fehler werden dort selbst behandelt. onDone(n, total)
 * meldet den Fortschritt nach jedem fertigen Element. */
async function runPool(items, limit, worker, onDone) {
  let next = 0, done = 0;
  const total = items.length;
  async function lane() {
    while (next < total) {
      const i = next++;
      try { await worker(items[i], i); } catch (e) { /* Fehler behandelt der worker */ }
      done++;
      if (onDone) onDone(done, total, items[i]);
    }
  }
  const lanes = [];
  for (let k = 0; k < Math.min(limit, total); k++) lanes.push(lane());
  await Promise.all(lanes);
}
/* Alle WKNs des Depots ohne Dubletten (Tranchen zählen einmal). */
function uniqueWkns(state) {
  return Array.from(new Set(state.positions.map(function (p) { return p.wkn; })));
}
function fmtNum(n, digits) {
  if (!validNumber(n)) return "–";
  return n.toLocaleString("de-DE", { minimumFractionDigits: digits || 0, maximumFractionDigits: digits || 0 });
}
function fmtPct(n) {
  if (!validNumber(n)) return "–";
  const rounded = Math.round(Math.abs(n) * 10) / 10;
  const s = rounded.toLocaleString("de-DE", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  return (n < 0 && rounded > 0 ? "−" : "+") + s + " %";
}
function esc(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

/* ---------------------------------------------------------------------------
 * Ablage (iCloud-Dokumente, wie bei den übrigen Scriptable-Projekten)
 * -------------------------------------------------------------------------*/

function storagePaths() {
  const fm = FileManager.iCloud();
  const dir = fm.joinPath(fm.documentsDirectory(), APP.name);
  if (!fm.fileExists(dir)) fm.createDirectory(dir, true);
  return { fm: fm, dir: dir, file: fm.joinPath(dir, APP.file) };
}

function defaultState() {
  return {
    theme: "system", positions: [], overrides: {}, names: {}, isinOverrides: {},
    overview: { etfs: {}, lastFetch: null, fundamentals: { items: {}, funds: {}, lastFetch: null }, history: [] },
    priceHistory: {},
    allocationProfile: "diversified",
    settings: { portalPriceFallback: true },
    fxRates: {},
    dividends: {},
    txHistory: {},   // Kaufhistorie je WKN: { at, items: [...] } aus comdirect-Depotumsätzen
    lastImport: null, lastPriceSync: null,
  };
}

/* Baut aus einer gelesenen Depotdatei den Laufzeit-Zustand (mit Migration alter Namenseinträge). */
function stateFromParsed(parsed) {
  // Migration: bis v1.x war state.names[wkn] ein reiner Namens-String; seit
  // v2.0 ein Objekt {name, symbol, exchange} (für den Kursverlauf). Alte
  // String-Einträge werden hier übernommen statt verworfen.
  const rawNames = (parsed && parsed.names) || {};
  const names = {};
  Object.keys(rawNames).forEach(function (wkn) {
    const entry = rawNames[wkn];
    names[wkn] = (typeof entry === "string") ? { name: entry, symbol: null, exchange: null } : entry;
  });
  if (parsed && parsed.settings) { delete parsed.settings.priceAlerts; delete parsed.settings.priceAlertNotifyMode; }   // Kursalarme entfernt
  return Object.assign(defaultState(), parsed, {
    overrides: Object.assign({}, parsed && parsed.overrides),
    names: names,
    isinOverrides: Object.assign({}, parsed && parsed.isinOverrides),
    overview: {
      etfs: Object.assign({}, parsed && parsed.overview && parsed.overview.etfs),
      lastFetch: (parsed && parsed.overview && parsed.overview.lastFetch) || null,
      fundamentals: normalizeFundamentals(parsed && parsed.overview && parsed.overview.fundamentals),
      history: (parsed && parsed.overview && Array.isArray(parsed.overview.history)) ? parsed.overview.history : [],
    },
    priceHistory: Object.assign({}, parsed && parsed.priceHistory),
    settings: Object.assign({ portalPriceFallback: true }, parsed && parsed.settings, {
    }),
    fxRates: Object.assign({}, parsed && parsed.fxRates),
    dividends: Object.assign({}, parsed && parsed.dividends),
    positions: (parsed && Array.isArray(parsed.positions)) ? parsed.positions : [],
  });
}

async function loadState() {
  try {
    const reg = await loadRegistry();
    return await loadDepotById(reg, reg.active);
  } catch (e) {
    logEvent("FEHLER", "Speicher", "Depot konnte nicht geladen werden — leerer Zustand: " + errText(e));
    const reg = getRegistry();
    return applyDepotMeta(defaultState(), reg, reg.depots[0]);
  }
}

/* ---------------------------------------------------------------------------
 * Seiten-Zwischenspeicher: Priorität und Durchschau (Analyse bzw. Overview) werden nur neu
 * berechnet, wenn sich Daten geändert haben. Jede Speicherung (saveState) erhöht
 * DATA_VER; zusätzlich gehören Depot, Darstellung (hell/dunkel) und Kalendertag zum
 * Schlüssel. Nach PAGE_CACHE_MAX_MS wird trotzdem neu gerechnet, weil die Seiten
 * relative Angaben enthalten („heute“, „nächste 12 Monate“).
 * --------------------------------------------------------------------------- */
let DATA_VER = 0;
const PAGE_CACHE = {};
const PAGE_CACHE_MAX_MS = 30 * 60 * 1000;
function markDataChanged() { DATA_VER++; }
function pageCacheKey(state) {
  const d = new Date();
  return [DATA_VER, state.depotId || "", state.depotKind || "", extResolvedTheme(state), Math.round(reserveCashEur(state)),
    d.getFullYear() + "-" + d.getMonth() + "-" + d.getDate()].join("|");
}
function cachedPage(name, state, build) {
  const key = pageCacheKey(state);
  const hit = PAGE_CACHE[name];
  if (hit && hit.key === key && Date.now() - hit.at < PAGE_CACHE_MAX_MS) return hit.html;
  const html = build();   // wirft bei Fehlern → nichts wird zwischengespeichert
  PAGE_CACHE[name] = { key: key, at: Date.now(), html: html };
  return html;
}

function saveState(state) {
  markDataChanged();
  try {
    applyCustomNames(state);
    const reg = getRegistry();
    if (!isAggregate(state)) {   // die Gesamtansicht ist nur berechnet und wird nie als Depotdatei gespeichert
      const dep = reg.depots.find(function (d) { return d.id === state.depotId; }) || reg.depots[0];
      const f = depotFilePath(dep);
      // iCloud-Schutz: leeren Zustand nie über eine Datei mit Positionen schreiben —
      // typischer Fall: zweites Gerät startet, bevor iCloud die Daten des anderen Geräts geliefert hat.
      if (!(state.positions && state.positions.length) && f.fm.fileExists(f.path)) {
        let disk = null;
        try { if (!f.fm.isFileDownloaded || f.fm.isFileDownloaded(f.path)) disk = JSON.parse(f.fm.readString(f.path)); } catch (e) { disk = null; }
        if (disk === null || (Array.isArray(disk.positions) && disk.positions.length)) {
          logEvent("WARNUNG", "Speicher", "„" + dep.name + "“: leerer Stand wurde NICHT gespeichert, weil die Datei in iCloud Positionen enthält bzw. noch nicht geladen ist — bitte 🔄 bzw. App neu starten.");
          return;
        }
      }
      // Konfliktschutz: hat ein anderes Gerät die Datei seit dem Laden geändert, nicht überschreiben.
      if (changedElsewhere(f.fm, f.path) || diskRev(f.fm, f.path) > (state.rev || 0)) {
        logEvent("WARNUNG", "Speicher", "„" + dep.name + "“ wurde inzwischen auf einem anderen Gerät geändert — Änderung hier NICHT gespeichert. Bitte Exchange neu öffnen (lädt den neuen Stand) und ggf. wiederholen.");
        return;
      }
      state.savedBy = deviceStamp();
      state.rev = (state.rev || 0) + 1;   // Revisionszähler: höhere Zahl = neuerer Stand (geräteübergreifend)
      f.fm.writeString(f.path, JSON.stringify(Object.assign({}, state, { customNames: undefined })));   // eigene Namen liegen in der Depotliste
      markSeen(f.fm, f.path);
    }
    // Gemeinsame Einstellungen (alle Depots) in der Depotliste festhalten.
    const sh = {
      theme: state.theme || "system",
      features: (state.settings && state.settings.features) || {},
      portalPriceFallback: !(state.settings && state.settings.portalPriceFallback === false),
      divvyDiary: !(state.settings && state.settings.divvyDiary === false),
      // Kaufideen-Schalter gelten für alle Depots (v2.78) — die Vorschläge selbst rechnet jedes Depot für sich
      buyIdeas: !!(state.settings && state.settings.buyIdeas === true),
      poolIdeas: !(state.settings && state.settings.poolIdeas === false),
      ai: !!(state.settings && state.settings.ai === true),
      customNames: state.customNames || (reg.shared && reg.shared.customNames) || {},
      tax: (state.settings && state.settings.tax) || (reg.shared && reg.shared.tax) || null,
      terOverrides: (state.settings && state.settings.terOverrides) || (reg.shared && reg.shared.terOverrides) || {},
      tfOverrides: (state.settings && state.settings.tfOverrides) || (reg.shared && reg.shared.tfOverrides) || {},
      tierOverrides: (state.settings && state.settings.tierOverrides) || (reg.shared && reg.shared.tierOverrides) || {},
    };
    if (JSON.stringify(sh) !== JSON.stringify(reg.shared)) { reg.shared = sh; saveRegistry(reg); }
  } catch (e) { logEvent("FEHLER", "Speicher", "Depotdatei konnte nicht gespeichert werden: " + errText(e)); }
}

/* ============================================================================
 * Depotverwaltung — mehrere Depots, je Depot eine eigene JSON-Datei
 * ---------------------------------------------------------------------------
 *  Ablage (iCloud/Scriptable/Depotbestand/):
 *    Depots.json           Depotliste (Name, Art, Dateiname), aktives Depot und die
 *                          für alle Depots gemeinsamen Einstellungen (Darstellung,
 *                          Zusatzfunktionen, Portalkurs-Schalter)
 *    depotbestand.json     das bisherige comdirect-Depot (unverändert, id „main“)
 *    depot_<id>.json       je zusätzlichem Depot eine eigene Datei
 *  Zusätzliche Depots sind „manuell“: Positionen werden per WKN, ISIN oder Kürzel,
 *  Stückzahl und Ø Kaufkurs von Hand erfasst (Zukauf, Stückzahl, Kaufkurs, Löschen
 *  über ⋯). Kurse, Overview, Verlauf, Kennzahlen, Dividenden laufen je Depot über
 *  dieselben Funktionen wie beim comdirect-Depot (🔄), jedes Depot mit eigenem Cache.
 * ==========================================================================*/

const DEPOT_REGISTRY_FILE = "Depots.json";
let DEPOT_REG = null;

function depotKindOf(state) { return state && state.depotKind ? state.depotKind : "comdirect"; }
function isManualDepot(state) { return depotKindOf(state) === "manual"; }
function depotKindLabel(kind) { return kind === "manual" ? "manuell erfasst" : (kind === "aggregate" ? "Gesamtansicht" : "comdirect (Import)"); }

function defaultRegistry() {
  return { version: 1, active: "main", depots: [{ id: "main", name: "comdirect-Depot", kind: "comdirect", file: APP.file }], shared: null, aggHistory: [] };
}
function getRegistry() {
  if (!DEPOT_REG) DEPOT_REG = defaultRegistry();
  return DEPOT_REG;
}
function registryPaths() {
  const s = storagePaths();
  return { fm: s.fm, dir: s.dir, path: s.fm.joinPath(s.dir, DEPOT_REGISTRY_FILE) };
}
function depotFilePath(dep) {
  const r = registryPaths();
  return { fm: r.fm, path: r.fm.joinPath(r.dir, dep.file) };
}
/* Geräteübergreifende Synchronisation */
const FILE_SEEN = {};   // Pfad → Änderungsdatum beim letzten Lesen/Schreiben durch dieses Gerät
function deviceStamp() {
  let n = "Gerät";
  try { n = Device.name() + " (" + Device.model() + ")"; } catch (e) { /* außerhalb iOS */ }
  return { device: n, at: new Date().toISOString() };
}
function fileMtime(fm, path) { try { const d = fm.modificationDate(path); return d ? d.getTime() : 0; } catch (e) { return 0; } }
function markSeen(fm, path) { FILE_SEEN[path] = fileMtime(fm, path); }
/* Wurde die Datei seit unserem Lesen von einem anderen Gerät geändert? */
function changedElsewhere(fm, path) {
  if (!(path in FILE_SEEN) || !fm.fileExists(path)) return false;
  return fileMtime(fm, path) > FILE_SEEN[path] + 1000;
}

/* Revision der Datei auf der Platte (0 = unbekannt/nicht lesbar). */
function diskRev(fm, path) {
  try {
    if (!fm.fileExists(path) || (fm.isFileDownloaded && !fm.isFileDownloaded(path))) return 0;
    const j = JSON.parse(fm.readString(path));
    return j && validNumber(j.rev) ? j.rev : 0;
  } catch (e) { return 0; }
}

/* Geräteabgleich: holt neuere iCloud-Stände (Depotliste + angezeigtes Depot bzw. alle Depots in
 * der Gesamtansicht) und lädt sie in das laufende state-Objekt. force = auch ohne erkannte
 * Änderung neu laden. Rückgabe: Text der Änderung oder null. */
let LAST_CLOUD_CHECK = 0;
async function syncFromCloud(state, force) {
  if (!force && Date.now() - LAST_CLOUD_CHECK < 15000) return null;
  LAST_CLOUD_CHECK = Date.now();
  const reg = getRegistry();
  const r = registryPaths();
  const files = [{ path: r.path, reg: true }];
  reg.depots.forEach(function (d) {
    if (isAggregate(state) || d.id === state.depotId) files.push({ path: depotFilePath(d).path, dep: d });
  });
  let changed = false, by = null;
  for (const x of files) {
    try {
      if (!r.fm.fileExists(x.path)) continue;
      if (r.fm.downloadFileFromiCloud) await r.fm.downloadFileFromiCloud(x.path);
      const newer = changedElsewhere(r.fm, x.path) || (x.dep && !isAggregate(state) && diskRev(r.fm, x.path) > (state.rev || 0));
      if (newer || force) {
        changed = changed || newer;
        try { const j = JSON.parse(r.fm.readString(x.path)); if (j.savedBy && newer) by = j.savedBy; } catch (e) { /* egal */ }
      }
    } catch (e) { /* offline: lokaler Stand */ }
  }
  if (!changed && !force) return null;
  const active = isAggregate(state) ? "all" : state.depotId;
  DEPOT_REG = null;
  const reg2 = await loadRegistry();
  const id = active === "all" ? (reg2.depots.length >= 2 ? "all" : reg2.depots[0].id)
    : (reg2.depots.some(function (d) { return d.id === active; }) ? active : reg2.depots[0].id);
  const loaded = await loadDepotById(reg2, id);
  Object.keys(state).forEach(function (k) { delete state[k]; });
  Object.assign(state, loaded);
  markDataChanged();
  if (!changed) return "unverändert";
  const msg = "Neuer Stand geladen" + (by ? " (gespeichert von " + by.device + ", " + new Date(by.at).toLocaleString("de-DE", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }) + ")" : "");
  logEvent("INFO", "iCloud", msg);
  return msg;
}

async function showToast(webView, text) {
  try {
    await webView.evaluateJavaScript("(function(){var d=document.createElement('div');d.textContent=" + JSON.stringify(text) +
      ";d.style.cssText='position:fixed;left:50%;top:calc(70px + env(safe-area-inset-top,0px));transform:translateX(-50%);z-index:99;max-width:90%;padding:10px 16px;border-radius:999px;font:600 14px -apple-system,system-ui;color:#fff;background:rgba(0,0,0,.78);-webkit-backdrop-filter:blur(20px);backdrop-filter:blur(20px);text-align:center';" +
      "document.body.appendChild(d);setTimeout(function(){d.remove();},3200);})();true;", false);
  } catch (e) { /* optional */ }
}

function saveRegistry(reg) {
  try {
    const r = registryPaths();
    // Mit der iCloud-Fassung zusammenführen: Depots, die ein anderes Gerät angelegt hat, behalten;
    // bewusst gelöschte (reg.deleted) bleiben gelöscht.
    if (r.fm.fileExists(r.path)) {
      try {
        const disk = JSON.parse(r.fm.readString(r.path));
        const del = {}; (reg.deleted || []).concat(disk.deleted || []).forEach(function (id) { del[id] = true; });
        const mine = {}; reg.depots.forEach(function (d) { mine[d.id] = true; });
        (disk.depots || []).forEach(function (d) { if (!mine[d.id] && !del[d.id]) reg.depots.push(d); });
        reg.deleted = Object.keys(del);
      } catch (e) { /* unlesbar: eigene Fassung schreiben */ }
    }
    reg.savedBy = deviceStamp();
    r.fm.writeString(r.path, JSON.stringify(reg));
    markSeen(r.fm, r.path);
  }
  catch (e) { logEvent("FEHLER", "Depots", "Depotliste konnte nicht gespeichert werden: " + errText(e)); }
}
/* Wartet höchstens ms Millisekunden auf ein Promise (iCloud-Downloads können sonst endlos hängen). */
function withTimeout(promise, ms, label) {
  return new Promise(function (resolve, reject) {
    let done = false;
    Timer.schedule(ms, false, function () { if (!done) { done = true; reject(new Error((label || "Vorgang") + ": Zeitlimit " + Math.round(ms / 1000) + " s")); } });
    Promise.resolve(promise).then(function (v) { if (!done) { done = true; resolve(v); } }, function (e) { if (!done) { done = true; reject(e); } });
  });
}
async function readFileText(fm, path) {
  if (!fm.fileExists(path)) return null;
  // Immer bei iCloud anfragen: holt auch eine neuere Version vom anderen Gerät — aber höchstens 15 s warten (ab v3.27)
  try { if (fm.downloadFileFromiCloud) await withTimeout(fm.downloadFileFromiCloud(path), 15000, "iCloud-Download " + String(path).split("/").pop()); }
  catch (e) { logEvent("WARNUNG", "iCloud", errText(e) + " — lokale Kopie wird verwendet."); }
  return fm.readString(path);
}

async function loadRegistry() {
  const r = registryPaths();
  let reg = null;
  try {
    const txt = await readFileText(r.fm, r.path);
    markSeen(r.fm, r.path);
    if (txt) reg = JSON.parse(txt);
  } catch (e) { logEvent("FEHLER", "Depots", "Depotliste nicht lesbar — Standard verwendet: " + errText(e)); }
  let dirty = false;
  if (!reg || !Array.isArray(reg.depots)) { reg = defaultRegistry(); dirty = true; }
  if (!reg.depots.some(function (d) { return d.id === "main"; })) { reg.depots.unshift(defaultRegistry().depots[0]); dirty = true; }
  reg.depots.forEach(function (d) {
    if (!d.file) d.file = d.id === "main" ? APP.file : "depot_" + d.id + ".json";
    if (!d.kind) d.kind = d.id === "main" ? "comdirect" : "manual";
    if (!d.name) d.name = "Depot";
  });
  if (!Array.isArray(reg.aggHistory)) reg.aggHistory = [];
  // Verzeichnis nach Depotdateien durchsuchen, die zwar auf der Platte liegen, aber (noch)
  // keinen Eintrag in Depots.json haben — z. B. nach einem Sync-Konflikt zwischen Geräten
  // oder wenn eine ältere Depots.json überschrieben wurde. Jede gefundene depot_<id>.json
  // wird als manuelles Depot ergänzt, damit keine Datei "verloren" geht.
  try {
    const names = r.fm.listContents(r.dir);
    const known = {};
    reg.depots.forEach(function (d) { known[d.file] = true; });
    (names || []).forEach(function (name) {
      if (known[name]) return;
      const m = /^depot_(.+)\.json$/.exec(name);
      if (!m) return;
      reg.depots.push({ id: m[1], name: "Wiederhergestelltes Depot", kind: "manual", file: name });
      known[name] = true;
      dirty = true;
    });
  } catch (e) { logEvent("FEHLER", "Depots", "Ordner konnte nicht nach Depotdateien durchsucht werden: " + errText(e)); }
  const activeOk = reg.depots.some(function (d) { return d.id === reg.active; }) || (reg.active === "all" && reg.depots.length >= 2);
  if (!activeOk) { reg.active = "main"; dirty = true; }
  if (!reg.shared) {
    // Erster Start nach dem Update: Darstellung/Zusatzfunktionen aus der bisherigen Depotdatei übernehmen.
    let seed = {};
    try { const t = await readFileText(r.fm, r.fm.joinPath(r.dir, APP.file)); if (t) seed = JSON.parse(t) || {}; } catch (e) { seed = {}; }
    reg.shared = {
      theme: seed.theme || "system",
      features: Object.assign({}, seed.settings && seed.settings.features),
      portalPriceFallback: !(seed.settings && seed.settings.portalPriceFallback === false),
    };
    dirty = true;
  }
  // Kursalarme entfernt (v2.77): Altdaten aus der Depotliste löschen
  if (reg.shared && ("priceAlerts" in reg.shared || "priceAlertNotifyMode" in reg.shared)) {
    delete reg.shared.priceAlerts; delete reg.shared.priceAlertNotifyMode;
    dirty = true;
  }
  if (dirty) saveRegistry(reg);
  DEPOT_REG = reg;
  return reg;
}

/* Darstellung, Zusatzfunktionen, Portalkurs-/DivvyDiary-Schalter und die Kaufideen-Schalter
 * (Neue Kaufideen, ETF-Kandidaten, KI-Vorschläge) gelten für alle Depots. */
function applyDepotMeta(st, reg, dep) {
  st.depotId = dep.id;
  st.depotName = dep.name;
  st.depotKind = dep.kind;
  const sh = reg.shared || {};
  if (sh.theme) st.theme = sh.theme;
  st.settings = Object.assign({}, st.settings, {
    features: Object.assign({}, sh.features),
    portalPriceFallback: sh.portalPriceFallback !== false,
    divvyDiary: sh.divvyDiary !== false,
  });
  // Kaufideen-Schalter depotübergreifend; ältere Depotlisten ohne Eintrag behalten den Depotwert
  if ("buyIdeas" in sh) st.settings.buyIdeas = sh.buyIdeas === true;
  if ("poolIdeas" in sh) st.settings.poolIdeas = sh.poolIdeas !== false;
  if ("ai" in sh) st.settings.ai = sh.ai === true;
  if (sh.tax) st.settings.tax = Object.assign({}, sh.tax);
  st.settings.terOverrides = Object.assign({}, sh.terOverrides);
  st.settings.tfOverrides = Object.assign({}, sh.tfOverrides);
  st.settings.tierOverrides = Object.assign({}, sh.tierOverrides);
  TIER_OVR = st.settings.tierOverrides;
  st.customNames = Object.assign({}, sh.customNames);
  applyCustomNames(st);
  return st;
}

/* Eigene Anzeigenamen: depotübergreifend in der Depotliste gespeichert
 * (reg.shared.customNames, Schlüssel = WKN/ISIN/Symbol). Sie überschreiben den
 * automatisch ermittelten Namen überall (Karten, Overview, Kurse, Kaufprioritäten)
 * und bleiben auch nach Import/Namensauflösung erhalten. autoName = Yahoo-Name. */
function customNameFor(st, wkn) {
  const cn = (st && st.customNames) || {};
  if (!Object.keys(cn).length) return null;
  const toks = identityTokens(st, wkn);
  for (let i = 0; i < toks.length; i++) if (cn[toks[i]]) return cn[toks[i]];
  return null;
}
function applyCustomNames(st) {
  if (!st || !st.names || !Array.isArray(st.positions)) return;
  const seen = {};
  st.positions.forEach(function (p) {
    if (!p.wkn || seen[p.wkn]) return;
    seen[p.wkn] = true;
    const c = customNameFor(st, p.wkn);
    const e = st.names[p.wkn];
    if (c) {
      if (e && e.custom && e.name === c) return;
      const auto = e ? (e.custom ? e.autoName : e.name) : null;
      st.names[p.wkn] = Object.assign({ symbol: null, exchange: null }, e, { name: c, custom: true, autoName: auto || null });
    } else if (e && e.custom) {
      const r = Object.assign({}, e, { name: e.autoName || p.wkn });
      delete r.custom; delete r.autoName;
      st.names[p.wkn] = r;
    }
  });
}

async function icloudStatusText() {
  const r = registryPaths();
  const docs = r.fm.documentsDirectory();
  const inCloud = /Mobile Documents|iCloud/i.test(docs);
  const lines = [];
  lines.push("Dieses Gerät: " + deviceStamp().device);
  lines.push("Speicherort: " + (inCloud ? "iCloud Drive ✓" : "LOKAL ✗ — iCloud Drive für Scriptable ist auf diesem Gerät aus; andere Geräte sehen diese Daten nicht"));
  lines.push("Ordner: " + r.dir);
  lines.push("");
  const fmt = function (t) { return t ? new Date(t).toLocaleString("de-DE") : "–"; };
  const info = async function (label, path) {
    if (!r.fm.fileExists(path)) { lines.push(label + ": fehlt"); return; }
    let by = "–";
    try { await readFileText(r.fm, path); const j = JSON.parse(r.fm.readString(path)); if (j.savedBy) by = j.savedBy.device + ", " + fmt(j.savedBy.at); 
      if (Array.isArray(j.positions)) label += " (" + j.positions.length + " Positionen)"; } catch (e) { by = "unlesbar: " + errText(e); }
    const dl = r.fm.isFileDownloaded ? (r.fm.isFileDownloaded(path) ? "geladen" : "nur in iCloud") : "";
    lines.push(label + "\n  geändert " + fmt(fileMtime(r.fm, path)) + (dl ? " · " + dl : "") + "\n  zuletzt gespeichert von: " + by);
  };
  await info("Depotliste (" + DEPOT_REGISTRY_FILE + ")", r.path);
  const reg = getRegistry();
  for (let i = 0; i < reg.depots.length; i++) await info("Depot „" + reg.depots[i].name + "“ (" + reg.depots[i].file + ")", depotFilePath(reg.depots[i]).path);
  try {
    const others = r.fm.listContents(r.dir).filter(function (n) { return / \d+\.json$/.test(n); });
    if (others.length) lines.push("\n⚠️ iCloud-Konfliktkopien gefunden: " + others.join(", ") + " — bitte melden bzw. prüfen.");
  } catch (e) { /* ignorieren */ }
  lines.push("\nHinweis: Beide Geräte müssen mit derselben Apple-ID angemeldet sein und iCloud Drive für Scriptable aktiv haben. Nach Änderungen auf einem Gerät Exchange auf dem anderen Gerät neu öffnen (nicht nur in den Vordergrund holen).");
  return lines.join("\n");
}

async function readDepotState(dep) {
  let parsed = null;
  try {
    const f = depotFilePath(dep);
    const txt = await readFileText(f.fm, f.path);
    markSeen(f.fm, f.path);
    if (txt) parsed = JSON.parse(txt);
  } catch (e) {
    logEvent("FEHLER", "Speicher", "Depotdatei „" + dep.name + "“ konnte nicht gelesen werden — leerer Zustand geladen: " + errText(e));
  }
  return stateFromParsed(parsed);
}

async function loadDepotById(reg, id) {
  if (id === "all" && reg.depots.length >= 2) return applyDepotMeta(await buildAggregateState(reg), reg, AGG_DEP);
  const dep = reg.depots.find(function (d) { return d.id === id; }) || reg.depots[0];
  return applyDepotMeta(await readDepotState(dep), reg, dep);
}

/* Tauscht den Inhalt des laufenden state-Objekts (Referenzen im Hauptablauf bleiben gültig).
 * id „all“ = Gesamtansicht (mind. 2 Depots). */
async function switchDepot(state, id) {
  const reg = getRegistry();
  if (id === "all" ? reg.depots.length < 2 : !reg.depots.some(function (d) { return d.id === id; })) return false;
  saveState(state);
  const loaded = await loadDepotById(reg, id);
  Object.keys(state).forEach(function (k) { delete state[k]; });
  Object.assign(state, loaded);
  reg.active = id;
  saveRegistry(reg);
  return true;
}

function newDepotId() { return "d" + Date.now().toString(36) + Math.floor(Math.random() * 1296).toString(36); }

/* Lädt alle Depotdateien aus iCloud herunter (falls noch nicht lokal vorhanden), bevor die
 * Depotverwaltung angezeigt wird. So erscheint ein auf einem anderen Gerät (z. B. iPad) neu
 * angelegtes Depot sofort korrekt mit Positionszahl/Wert, statt vorübergehend als „keine Datei“. */
async function ensureDepotFilesDownloaded(reg) {
  for (const dep of reg.depots) {
    try {
      const f = depotFilePath(dep);
      if (f.fm.fileExists(f.path) && f.fm.isFileDownloaded && !f.fm.isFileDownloaded(f.path)) {
        await f.fm.downloadFileFromiCloud(f.path);
      }
    } catch (e) { /* Zusammenfassung ist nur Zierde */ }
  }
}

function depotSummary(state, dep) {
  try {
    let st = null;
    if (dep.id === state.depotId) st = state;
    else {
      const f = depotFilePath(dep);
      if (f.fm.fileExists(f.path)) st = JSON.parse(f.fm.readString(f.path));
    }
    if (st && Array.isArray(st.positions)) {
      const value = st.positions.reduce(function (s, p) { return s + (validNumber(p.currentPrice) && validNumber(p.qty) ? p.currentPrice * p.qty : 0); }, 0);
      return { positions: st.positions.length, value: value };
    }
  } catch (e) { /* Zusammenfassung ist nur Zierde */ }
  return { positions: null, value: null };
}

function setRowHtml(href, title, sub, right, cls) {
  return "<a class=\"set-row\" href=\"scriptable:" + href + "\"><span class=\"set-main\"><b>" + esc(title) + "</b>" +
    (sub ? "<small>" + esc(sub) + "</small>" : "") + "</span><span class=\"set-right" + (cls ? " " + cls : "") + "\">" + esc(right || "›") + "</span></a>";
}

function depotsHtml(state) {
  const reg = getRegistry();
  const rows = reg.depots.map(function (dep) {
    const sm = depotSummary(state, dep);
    const active = dep.id === state.depotId;
    const sub = depotKindLabel(dep.kind) + " · " + (sm.positions === null ? "keine Datei" : sm.positions + " Position(en)" + (sm.positions ? " · " + fmtEur(sm.value) : "")) + " · " + dep.file;
    return setRowHtml("depot?id=" + encodeURIComponent(dep.id), dep.name, sub, active ? "● aktiv" : "○", active ? "sel" : "");
  }).join("");
  let aggRow = "";
  if (reg.depots.length >= 2) {
    let n = 0, val = 0;
    reg.depots.forEach(function (dep) { const sm = depotSummary(state, dep); if (sm.positions !== null) { n += sm.positions; val += sm.value || 0; } });
    const on = isAggregate(state);
    aggRow = "<div class=\"set-group\">" + setRowHtml("depot-open?id=all", "Σ Alle Depots", reg.depots.length + " Depots zusammen · " + n + " Position(en) · " + fmtEur(val) + " · nur Ansicht", on ? "● aktiv" : "○", on ? "sel" : "") + "</div>";
  }
  const histRow = "<div class=\"set-group\">" + setRowHtml("history", "📜 History", "verkaufte ETFs und Aktien, die nicht mehr im comdirect-Depot liegen · realisierter G/V, Haltedauer, Dividenden · nur Ansicht") + "</div>";
  return "<div class=\"chart-view page\"><h2>Depotverwaltung</h2>" + aggRow +
    "<div class=\"set-group\">" + rows + "</div>" + histRow +
    "<div class=\"set-group\">" + setRowHtml("depot-add", "＋ Neues Depot anlegen", "manuell erfasst — Positionen selbst hinzufügen") + "</div>" +
    "<div class=\"note\">Depot antippen: öffnen, umbenennen oder löschen. Jedes Depot liegt in einer eigenen Datei und hat eigene Kurse, Overview, Verlauf und Kennzahlen. Darstellung und Zusatzfunktionen gelten für alle Depots. Das comdirect-Depot lässt sich umbenennen, aber nicht löschen.</div></div>";
}

async function depotAddMenu(state) {
  const a = new WebAlert();
  a.title = "Neues Depot";
  a.message = "Ein manuell erfasstes Depot mit eigener Datei. Positionen fügst du danach mit ＋ hinzu.";
  a.addTextField("Name", "Depot " + (getRegistry().depots.length + 1));
  a.addAction("Anlegen");
  a.addCancelAction("Abbrechen");
  if ((await a.presentAlert()) !== 0) return false;
  const name = String(a.textFieldValue(0) || "").trim().slice(0, 40);
  if (!name) return false;
  const reg = getRegistry();
  const id = newDepotId();
  const dep = { id: id, name: name, kind: "manual", file: "depot_" + id + ".json" };
  reg.depots.push(dep);
  try {
    const f = depotFilePath(dep);
    f.fm.writeString(f.path, JSON.stringify(applyDepotMeta(defaultState(), reg, dep)));
  } catch (e) { logEvent("FEHLER", "Depots", "Depotdatei konnte nicht angelegt werden: " + errText(e)); }
  saveRegistry(reg);
  return await switchDepot(state, id);
}

/* Rückgabe true = Depot wurde gewechselt (Liste neu zeichnen). */
async function depotMenu(state, id) {
  const reg = getRegistry();
  const dep = reg.depots.find(function (d) { return d.id === id; });
  if (!dep) return false;
  const a = new WebAlert();
  a.title = dep.name;
  a.message = depotKindLabel(dep.kind) + " · Datei: " + dep.file;
  const acts = [];
  if (dep.id !== state.depotId) { a.addAction("Öffnen"); acts.push("open"); }
  a.addAction("Umbenennen"); acts.push("rename");
  if (dep.kind === "manual") { a.addDestructiveAction("Depot löschen"); acts.push("delete"); }
  a.addCancelAction("Abbrechen");
  const c = await a.presentAlert();
  if (c < 0) return false;
  const act = acts[c];
  if (act === "open") return await switchDepot(state, dep.id);
  if (act === "rename") {
    const r = new WebAlert();
    r.title = "Depot umbenennen";
    r.addTextField("Name", dep.name);
    r.addAction("Speichern");
    r.addCancelAction("Abbrechen");
    if ((await r.presentAlert()) !== 0) return false;
    const name = String(r.textFieldValue(0) || "").trim().slice(0, 40);
    if (!name) return false;
    dep.name = name;
    if (dep.id === state.depotId) state.depotName = name;
    saveRegistry(reg);
    return dep.id === state.depotId;   // Titel neu zeichnen
  }
  if (act === "delete") {
    const d = new WebAlert();
    d.title = "Depot löschen?";
    d.message = "„" + dep.name + "“ und seine Datei (" + dep.file + ") werden endgültig entfernt.";
    d.addDestructiveAction("Endgültig löschen");
    d.addCancelAction("Abbrechen");
    if ((await d.presentAlert()) !== 0) return false;
    let switched = false;
    if (dep.id === state.depotId) switched = await switchDepot(state, "main");
    try { const f = depotFilePath(dep); if (f.fm.fileExists(f.path)) f.fm.remove(f.path); }
    catch (e) { logEvent("WARNUNG", "Depots", "Datei " + dep.file + " konnte nicht entfernt werden: " + errText(e)); }
    reg.depots = reg.depots.filter(function (x) { return x.id !== dep.id; });
    reg.deleted = (reg.deleted || []).concat([dep.id]);   // damit das andere Gerät es nicht zurückbringt
    saveRegistry(reg);
    return switched;
  }
  return false;
}

