const DIALOG_MARKUP =
  "<div id=\"dlg\" class=\"dlg hidden\"></div>" +
  "<div id=\"sub\" class=\"sub hidden\"><div class=\"sub-bar\">" +
  "<span class=\"sub-title\" id=\"sub-title\"></span><a class=\"sub-act hidden\" id=\"sub-act\" href=\"#\"></a></div>" +
  "<iframe id=\"sub-frame\"></iframe><pre id=\"sub-text\"></pre></div>";

const DIALOG_JS = String.raw`
(function(){
  function el(tag, cls, txt){ var e=document.createElement(tag); if(cls) e.className=cls; if(txt!=null) e.textContent=txt; return e; }
  window.dlg = function(spec, done){
    var root=document.getElementById('dlg');
    if(window.__dlgDone){ var prev=window.__dlgDone; window.__dlgDone=null; prev({button:-1,values:[]}); }
    root.innerHTML='';
    var box=el('div','dlg-box');
    if(spec.title) box.appendChild(el('div','dlg-title',spec.title));
    var body=el('div','dlg-body');
    if(spec.message) body.appendChild(el('div','dlg-msg',spec.message));
    var inputs=[];
    (spec.fields||[]).forEach(function(f){
      var wrap=el('label','dlg-field');
      wrap.appendChild(el('span','dlg-lbl',f.label||''));
      var inp=document.createElement('input');
      inp.type=f.secure?'password':'text';
      inp.value=f.value||'';
      inp.setAttribute('autocapitalize','off'); inp.setAttribute('autocorrect','off'); inp.setAttribute('autocomplete','off');
      inp.spellcheck=false;
      wrap.appendChild(inp); body.appendChild(wrap); inputs.push(inp);
    });
    box.appendChild(body);
    var row=el('div','dlg-btns'), cancelIdx=-1, primaryIdx=-1, closed=false;
    function finish(i){
      if(closed) return; closed=true; window.__dlgDone=null;
      var vals=inputs.map(function(x){ return x.value; });
      root.classList.add('hidden'); root.innerHTML='';
      done({button:i, values:vals});
    }
    (spec.buttons||[]).forEach(function(b,i){
      var btn=el('button','dlg-btn'+(b.style?' '+b.style:''),b.label);
      if(b.style==='cancel') cancelIdx=i;
      if(b.style==='primary' && primaryIdx<0) primaryIdx=i;
      btn.addEventListener('click',function(){ finish(i); });
      row.appendChild(btn);
    });
    box.appendChild(row);
    root.appendChild(box);
    inputs.forEach(function(inp){ inp.addEventListener('keydown',function(e){ if(e.key==='Enter' && primaryIdx>=0){ e.preventDefault(); finish(primaryIdx); } }); });
    root.onclick=function(e){ if(e.target===root && cancelIdx>=0) finish(cancelIdx); };
    window.__dlgDone=done;
    root.classList.remove('hidden');
    if(inputs[0]) setTimeout(function(){ inputs[0].focus(); },60);
  };
  /* Unterseite zwischen Kopfzeile und Tab-Leiste einpassen — beide bleiben sichtbar. */
  function fitSub(){
    var sub=document.getElementById('sub'), h=document.querySelector('header'), t=document.getElementById('tabbar');
    if(!sub) return;
    var top=h?h.getBoundingClientRect().bottom:0, bottom=t?t.offsetHeight:0;
    if(top<0) top=0;
    sub.style.setProperty('--sub-top', top+'px');
    sub.style.setProperty('--sub-bottom', bottom+'px');
    sub.classList.toggle('docked', top>0);
  }
  function setHH(){ var h=document.querySelector('header'); if(h) document.documentElement.style.setProperty('--hh', h.getBoundingClientRect().height + 'px'); }
  setHH(); setTimeout(setHH, 300);
  window.addEventListener('resize', setHH);
  window.addEventListener('orientationchange', function(){ setTimeout(setHH, 250); });
  window.addEventListener('resize', function(){ if(document.body.classList.contains('sub-open')) fitSub(); });
  window.addEventListener('orientationchange', function(){ setTimeout(fitSub, 250); });
  /* Tipp auf Kopfzeile/Tabs bei offener Unterseite: Unterseite schließen (außer ◐ Darstellung),
     angetippten Tab markieren. Die eigentliche Aktion läuft normal weiter. */
  document.addEventListener('click', function(e){
    var a=e.target && e.target.closest ? e.target.closest('header a, #tabbar a') : null;
    if(!a) return;
    var href=a.getAttribute('href')||'';
    var opensSub=/^scriptable:(overview|market|priorities|dividends|analysis|finance)$/.test(href);
    if(href!=='scriptable:theme' && href!=='scriptable:privacy' && !opensSub && document.body.classList.contains('sub-open')) window.closeSub();
    if(a.closest('#tabbar')){
      Array.prototype.forEach.call(document.querySelectorAll('#tabbar a'), function(x){ x.classList.remove('cur'); });
      if(href!=='scriptable:back') a.classList.add('cur');
    }
  }, true);
  function showSub(title, asFrame, action){
    document.getElementById('sub-title').textContent=title||'';
    var act=document.getElementById('sub-act');
    if(action && action.href){ act.textContent=action.label||''; act.setAttribute('href',action.href); act.classList.remove('hidden'); }
    else { act.classList.add('hidden'); act.setAttribute('href','#'); }
    document.getElementById('sub-frame').style.display=asFrame?'block':'none';
    document.getElementById('sub-text').style.display=asFrame?'none':'block';
    document.body.classList.add('sub-open');
    fitSub();
    document.getElementById('sub').classList.remove('hidden');
  }
  window.openSub=function(title, html){ showSub(title,true); document.getElementById('sub-frame').srcdoc=html; };
  window.openSubText=function(title, text, action){
    showSub(title,false,action);
    var t=document.getElementById('sub-text'); t.textContent=text; t.scrollTop=t.scrollHeight;
  };
  window.closeSub=function(){
    document.body.classList.remove('sub-open');
    Array.prototype.forEach.call(document.querySelectorAll('#tabbar a.cur'), function(x){ x.classList.remove('cur'); });
    document.getElementById('sub').classList.add('hidden');
    document.getElementById('sub-frame').srcdoc='';
    document.getElementById('sub-text').textContent='';
  };
})();
`;

async function editPriceMenu(state, positionId) {
  const eff = effectivePrice(state, positionId);
  const pos = state.positions.find(function (x) { return x.positionId === positionId; });
  const info = pos ? state.names[pos.wkn] : null;
  const label = pos
    ? ((info && info.name || pos.wkn) + (lockDateLabel(pos.lockDate) ? " · " + lockDateLabel(pos.lockDate) : ""))
    : positionId;
  const a = new WebAlert();
  a.title = "Ø Kaufkurs — " + label;
  a.message = eff.manual
    ? (eff.adjusted ? "Aktuell fortgeschrieben (manuell + Zukauf): " : "Aktuell manuell eingetragen: ") + fmtEur(eff.price)
    : "Aktuell von comdirect übernommen: " + fmtEur(eff.price);
  a.addTextField("Kaufkurs in EUR", validNumber(eff.price) ? String(eff.price).replace(".", ",") : "");
  a.addAction("Speichern");
  if (state.overrides[positionId]) a.addDestructiveAction("Manuellen Wert entfernen");
  a.addCancelAction("Abbrechen");
  const choice = await a.presentAlert();
  if (choice === -1) return;
  if (choice === 1 && state.overrides[positionId]) {
    delete state.overrides[positionId];
    saveState(state);
    return;
  }
  const value = userNumber(a.textFieldValue(0));
  if (value === null || value <= 0) {
    const err = new WebAlert();
    err.title = "Ungültiger Wert";
    err.message = "Bitte eine Zahl größer 0 eingeben.";
    err.addAction("OK");
    await err.presentAlert();
    return;
  }
  state.overrides[positionId] = { price: value };
  saveState(state);
}

/* Manuelle Namenskorrektur — vor allem für Positionen, die sich nicht
 * automatisch über Yahoo Finance auflösen lassen (z. B. interne VL-/
 * Vermögensbildungsfonds ohne öffentliches Kurssymbol). */
/* Versucht zu einem bekannten Yahoo-Finance-Symbol den Namen nachzuladen
 * (z. B. wenn nur das Kurssymbol manuell eingetragen wurde). */
async function fetchYahooQuoteName(symbol) {
  try {
    const data = await loadJsonUrl("https://query1.finance.yahoo.com/v8/finance/chart/" + encodeURIComponent(symbol) + "?range=1d&interval=1d");
    const res = data && data.chart && data.chart.result && data.chart.result[0];
    const meta = res && res.meta;
    if (!meta) return null;
    const name = String(meta.longName || meta.shortName || "").trim();
    return name ? { name: name, exchange: String(meta.fullExchangeName || meta.exchangeName || "") } : null;
  } catch (e) {
    return null;
  }
}

async function editNameMenu(state, wkn) {
  applyCustomNames(state);
  const existing = state.names[wkn];
  const existingIsin = state.isinOverrides[wkn];
  const autoName = existing ? (existing.custom ? existing.autoName : existing.name) : null;
  const isCustom = !!(existing && existing.custom);
  const a = new WebAlert();
  a.title = "Name / ISIN / Symbol — " + displayIds(state, wkn);
  a.message = (isCustom ? "Eigener Name aktiv. Automatisch ermittelt: " + (autoName || "–") : (existing
    ? "Automatisch ermittelt: " + existing.name
    : "Für dieses Wertpapier wurde kein Name automatisch gefunden.")) +
    (existing && existing.symbol ? "\nKurssymbol: " + existing.symbol : "") +
    "\n\nDer Name gilt in allen Depots und bleibt auch nach Import und Aktualisierung erhalten. Feld leeren = automatischer Name.";
  a.addTextField("Anzeigename", (existing && existing.name) || "");
  a.addTextField("ISIN für automatische Auflösung (optional)", existingIsin || "");
  a.addTextField("Kurssymbol, z. B. CBK.DE (optional)", (existing && existing.symbol) || "");
  a.addAction("Speichern");
  if (isCustom) a.addAction("Automatischen Namen verwenden");
  if (existing || existingIsin) a.addDestructiveAction("Alles zurücksetzen");
  a.addCancelAction("Abbrechen");
  const choice = await a.presentAlert();
  if (choice === -1) return;
  if (!state.customNames) state.customNames = {};
  const dropCustom = function () {
    identityTokens(state, wkn).forEach(function (t) { delete state.customNames[t]; });
  };
  if (isCustom && choice === 1) { dropCustom(); saveState(state); return; }
  const resetIdx = isCustom ? 2 : 1;
  if (choice === resetIdx && (existing || existingIsin)) {
    dropCustom();
    delete state.names[wkn];
    delete state.isinOverrides[wkn];
    saveState(state);
    return;
  }
  const name = a.textFieldValue(0).trim();
  const isinRaw = a.textFieldValue(1).trim();
  const symbolRaw = a.textFieldValue(2).trim();
  if (isinRaw && !normalizeIsinInput(isinRaw)) {
    await infoDialog("Ungültige ISIN", "Eine ISIN hat 12 Zeichen (2 Buchstaben Länderkürzel + 10 alphanumerische Zeichen).");
    return;
  }
  const isinInput = normalizeIsinInput(isinRaw);
  const isinChanged = isinInput !== (existingIsin || null);
  if (isinInput) state.isinOverrides[wkn] = isinInput; else delete state.isinOverrides[wkn];

  // Anzeigename: abweichend vom automatischen Namen = eigener Name, leer/gleich = automatisch.
  dropCustom();
  if (name && name !== autoName) state.customNames[wkn] = name;

  const symbolChanged = symbolRaw !== ((existing && existing.symbol) || "");
  if (symbolRaw && symbolChanged) {
    let exchange = (existing && existing.exchange) || null, auto = autoName;
    const looked = await fetchYahooQuoteName(symbolRaw);
    if (looked) { auto = looked.name; exchange = looked.exchange; }
    state.names[wkn] = { name: auto || wkn, symbol: symbolRaw, exchange: exchange };
  } else if (!symbolRaw && existing && existing.symbol && !isinChanged) {
    state.names[wkn] = { name: autoName || wkn, symbol: null, exchange: null };
  } else if (isinChanged && !symbolRaw) {
    // neue/andere ISIN ohne Symbol: Cache leeren, nächste Synchronisierung löst neu auf
    delete state.names[wkn];
  }
  applyCustomNames(state);
  saveState(state);
}


