function assetTier(etf, state) { return tierAssess(etf || {}, state).tier; }
/* Notlösung ohne Kurshistorie: bisherige Namensregel. */
function nameTier(etf) {
  if (isStock(etf)) return "satellite";
  const n = String((etf && etf.name) || "");
  if (/(anleihe|bond|treasury|govt|staatsanl|geldmarkt|money ?market|overnight|€str|\bestr\b|t-bill|cash)/i.test(n)) return "reserve";
  const broad = /(world|welt|acwi|all[- ]?countr|all[- ]?world|s&p ?500|\bsp ?500|msci usa|total (world|market|stock)|ftse developed|developed (markets|world)|stoxx (europe )?600)/i.test(n);
  const theme = /(tech|information|health|energy|financ|consumer|industr|utilit|material|real estate|immobil|semiconductor|robot|clean|water|wasser|\bai\b|artificial|dividend|momentum|\bvalue\b|quality|min(imum)? ?vol|small ?cap|defen[cs]e|cyber|gold|bitcoin|crypto)/i.test(n);
  return broad && !theme ? "core" : "satellite";
}

/* Qualität 0…1: Bewertung (KGV 40 %), langfristige Rendite (35 %), Dividende (25 %). */
function qualityScore(etf, kz, f) {
  f = f || 0;
  const pe = kz && validNumber(kz.pe) && kz.pe > 0 ? kz.pe : null;
  let peN = 0.5;
  if (pe !== null) {
    if (pe <= 12) peN = 1;
    else if (pe <= 20) peN = 1 - (pe - 12) / 8 * 0.4;
    else if (pe <= 30) peN = 0.6 - (pe - 20) / 10 * 0.35;
    else peN = 0.15;
  }
  const ex = recommendationExpectedGrowth(etf);
  const exN = ex.value === null ? 0.5 : clampScore((ex.value + 5) / 20, 0, 1);
  const dv = recommendationDividendMetrics(etf);
  // Ruhestand: Dividende 25 → 40 %, langfristige Rendite 35 → 20 %.
  return { q: clampScore(peN * 0.40 + exN * (0.35 - 0.15 * f) + dv.norm * (0.25 + 0.15 * f), 0, 1), pe: pe, peNorm: peN };
}

function recommendationTargetShares(recEtfs, state, kzByWkn, opt) {
  const n = recEtfs.length;
  const out = { shares: [], tiers: [], quality: [], cashShare: 0 };
  // 🏦 Tagesgeld (opt.cash, €) ist Teil der Reserve; Anteile beziehen sich auf Depot + Tagesgeld.
  const cash = opt && validNumber(opt.cash) && opt.cash > 0 ? opt.cash : 0;
  if (!n) return out;
  const profile = allocationProfile(state);
  const tiers = recEtfs.map(function (e) { return assetTier(e, state); });
  const rf = retirementF(state);
  const quality = recEtfs.map(function (e) { return qualityScore(e, kzByWkn ? kzByWkn[e.wkn] : null, rf); });
  const idx = { core: [], satellite: [], reserve: [] };
  tiers.forEach(function (t, i) { idx[t].push(i); });

  const reservePool = idx.reserve.length || cash > 0 ? (idx.core.length || idx.satellite.length ? reservePct(state) : 100) : 0;
  const rest = 100 - reservePool;
  let corePool = 0, satPool = 0;
  if (idx.core.length && idx.satellite.length) {
    // Ruhestand: Satellitenanteil schrumpft bis auf die Hälfte, der Rest geht in den Kern.
    satPool = rest * (100 - (CORE_PCT[profile] || 80)) / 100 * (1 - 0.5 * rf);
    corePool = rest - satPool;
  }
  else if (idx.core.length) corePool = rest;
  else satPool = rest;

  const shares = new Array(n).fill(0);
  if (cash > 0) {
    // Reserve-Soll gemeinsam für Tagesgeld und Reserve-ETFs, aufgeteilt nach heutigem Wert —
    // so steht jede Reserve-Position genau dann „am Soll“, wenn die Reserve insgesamt am Soll ist.
    const rv = idx.reserve.map(function (i) { const v = opt.values ? opt.values[i] : null; return validNumber(v) && v > 0 ? v : 0; });
    const rsum = cash + rv.reduce(function (s, v) { return s + v; }, 0);
    out.cashShare = reservePool * cash / rsum;
    idx.reserve.forEach(function (i, k) { shares[i] = reservePool * rv[k] / rsum; });
  }
  else idx.reserve.forEach(function (i) { shares[i] = reservePool / idx.reserve.length; });

  // Satelliten: Gewicht ∝ (0,25 + Qualität)² — Überzeugung konzentrieren, mit Deckel je Position.
  if (idx.satellite.length) {
    const w = {}; idx.satellite.forEach(function (i) { w[i] = Math.pow(0.25 + quality[i].q, 2); });
    let open = idx.satellite.slice(), pool = satPool, overflow = 0;
    for (let round = 0; round < 6 && open.length && pool > 1e-9; round++) {
      const sum = open.reduce(function (s, i) { return s + w[i]; }, 0) || 1;
      let excess = 0;
      const still = [];
      open.forEach(function (i) {
        // Deckel nur, wenn ein Kern existiert, der das Übergewicht aufnehmen kann.
        const cap = !idx.core.length ? Infinity : (isStock(recEtfs[i]) ? stockCap(state) : THEME_CAP);
        const add = pool * w[i] / sum;
        if (shares[i] + add > cap) { excess += shares[i] + add - cap; shares[i] = cap; }
        else { shares[i] += add; still.push(i); }
      });
      open = still;
      pool = 0;
      if (excess > 0) { if (idx.core.length) overflow += excess; else pool = excess; }
    }
    corePool += overflow;
  }
  if (idx.core.length) idx.core.forEach(function (i) { shares[i] = corePool / idx.core.length; });
  else if (corePool > 1e-9 && idx.reserve.length) idx.reserve.forEach(function (i) { shares[i] += corePool / idx.reserve.length; });

  out.shares = shares; out.tiers = tiers; out.quality = quality;
  return out;
}


function recommendationDataStatus(etf, course, expected, allocation, dividend) {
  const missing = [];
  const amount = overviewToNumber(etf && etf.amount);
  if (amount === null || amount <= 0) missing.push("Anzahl");
  if (!validNumber(currentMarketPrice(etf))) missing.push("aktueller Kurs");
  if (!course || course.parts < 1 || course.trend === null) missing.push("Kursverlauf");
  if (!expected || expected.parts < 1 || expected.value === null) missing.push("Kurshistorie");
  if (!isStock(etf)) {
    if (!allocation || allocation.sectorNorm === null) missing.push("Sektoren");
    if (!allocation || allocation.regionNorm === null) missing.push("Regionen");
  }
  if (marketQuality(etf).symbolSuspect) missing.push("Symbol/Kurszuordnung");
  if (!isStock(etf) && distributionType(etf) === "distributing" && (!dividend || dividend.yieldPct === null)) missing.push("Ausschüttungen");
  return { complete: missing.length === 0, scoreAllowed: missing.length === 0, missing: missing, critical: missing };
}

function recommendationAnalysis(state) {
  const recEtfs = buildOverviewEtfs(state).map(function (e) {
    const hist = state.priceHistory[e.wkn];
    const points = (hist && hist.points) || [];
    const dv = dividendEventsFor(state, e.wkn);
    const dividends = dv.events.length ? dividendSummaryFromEvents(dv.events, e.currentPrice, dv.currency, state) : null;
    const perShare = dividends && validNumber(dividends.trailing12mAmountEur) && dividends.trailing12mAmountEur > 0 ? dividends.trailing12mAmountEur : null;
    return Object.assign({}, e, {
      market: { history: points, totalReturnHistory: [], performance: computePerformance(points), dividends: dividends, quality: {} },
      divIncomeEur: perShare !== null && validNumber(e.amount) ? perShare * e.amount : null,
    });
  });
  // Höhe der Dividende: Anteil jeder Position an den Depot-Dividenden und Depot-Ø-Rendite.
  const divTotal = recEtfs.reduce(function (s, x) { return s + (x.divIncomeEur || 0); }, 0);
  const divValue = recEtfs.reduce(function (s, x) { return s + (positionMarketValue(x) || 0); }, 0);
  const depotYield = divValue > 0 ? divTotal / divValue * 100 : null;
  recEtfs.forEach(function (x) {
    x.divSharePct = divTotal > 0 && validNumber(x.divIncomeEur) ? x.divIncomeEur / divTotal * 100 : null;
    x.depotYieldPct = depotYield;
  });
  const values = recEtfs.map(positionMarketValue);
  const resCash = reserveCashEur(state);   // 🏦 Tagesgeld-Konten als Reserve
  const valueTotal = values.reduce(function (s, v) { return s + (v || 0); }, 0) + resCash;
  const kzByWkn = {};
  try { buildKennzahlenModel(state).funds.forEach(function (f) { kzByWkn[f.wkn] = f; }); }
  catch (e) { logEvent("FEHLER", "Kaufpriorität", "Kennzahlen (KGV) nicht verfügbar: " + errText(e)); }
  const tgt = recommendationTargetShares(recEtfs, state, kzByWkn, { cash: resCash, values: values });
  const targets = tgt.shares;
  const profile = allocationProfile(state);
  const weights = recommendationProfileWeights(state);
  // Streuung: Einzelaktien haben keine Regionen-/Sektordaten. Statt fix 0,42 (systematisch ~9 Punkte Abzug)
  // erhalten sie den Ø der ETFs im Depot — neutral gegenüber den übrigen Positionen. Das Klumpenrisiko
  // einzelner Aktien begrenzen Sollgewicht und Deckel (10 % je Aktie).
  const allocs = recEtfs.map(function (etf) { return recommendationAllocationMetrics(etf, recEtfs); });
  const etfAllocNorms = allocs.filter(function (a, i) { return !isStock(recEtfs[i]) && (a.sectorNorm !== null || a.regionNorm !== null); }).map(function (a) { return a.norm; });
  const stockAllocNorm = etfAllocNorms.length ? etfAllocNorms.reduce(function (s, x) { return s + x; }, 0) / etfAllocNorms.length : 0.5;
  allocs.forEach(function (a, i) {
    if (!isStock(recEtfs[i])) return;
    a.norm = stockAllocNorm;
    a.note = "Einzelaktie ohne Regionen-/Sektordaten — neutral mit dem ETF-Ø " + Math.round(stockAllocNorm * 100) + "/100 bewertet";
  });

  const rows = recEtfs.map(function (etf, idx) {
    const value = values[idx];
    const share = valueTotal > 0 && value !== null ? (value / valueTotal) * 100 : null;
    const targetShare = validNumber(targets[idx]) ? targets[idx] : (recEtfs.length ? 100 / recEtfs.length : 0);
    const tier = tgt.tiers[idx] || "satellite";
    const bq = tgt.quality[idx] || { q: 0.5, pe: null, peNorm: 0.5 };
    const course = recommendationCourseMetrics(etf);
    const expected = recommendationExpectedGrowth(etf);
    const allocation = allocs[idx];
    const dividend = recommendationDividendMetrics(etf);
    const dataStatus = recommendationDataStatus(etf, course, expected, allocation, dividend);
    const expectedNorm = expected.value === null ? 0.5 : clampScore((expected.value + 10) / 35, 0, 1);
    let raw = course.norm * weights.course + expectedNorm * weights.expected + allocation.norm * weights.allocation + dividend.norm * weights.dividend +
      (weights.quality ? bq.q * weights.quality : 0);
    if (profile === "safety" && isStock(etf)) raw *= 0.88;
    const score = dataStatus.scoreAllowed ? Math.round(clampScore(raw, 0, 100)) : null;

    let label = "⚠️ Daten unvollständig – keine Empfehlung";
    if (score !== null) {
      label = "🔴 Derzeit nicht aufstocken";
      if (score >= 75) label = "🟢 Hohe Aufstockungspriorität";
      else if (score >= 60) label = "🟢 Aufstocken";
      else if (score >= 45) label = "🟡 Beobachten";
      else if (score >= 30) label = "⚪ Halten";
    }

    const reasons = [];
    if (dataStatus.missing.length) reasons.push("fehlende Daten: " + dataStatus.missing.join(", "));
    if (course.trend === null) reasons.push("Kursverlauf: zu wenig Daten");
    else {
      let t = "Kursverlauf " + (course.trend >= 0 ? "+" : "") + course.trend.toFixed(1) + " %";
      if (course.maxDrawdown !== null) t += ", max. Rückgang 1J " + course.maxDrawdown.toFixed(1) + " %";
      reasons.push(t);
    }
    if (expected.value === null) reasons.push("Kurserwartung: nicht belastbar berechenbar");
    else reasons.push("historisch abgeleitete Kurserwartung ca. " + (expected.value >= 0 ? "+" : "") + expected.value.toFixed(1) + " % p.a.");
    if (etf.synthetic) {
      reasons.push("synthetischer ETF: Bewertung nutzt Index-Exposure, nicht Swap-Sicherheiten");
      if (etf.sectorInferredFromIndex) reasons.push("Sektor aus eindeutigem Referenzindex abgeleitet");
    }
    if (allocation.sectorTop) reasons.push("größter Sektor " + allocation.sectorTop.name + " " + allocation.sectorTop.weight.toFixed(1) + " %");
    if (allocation.regionTop) reasons.push("größte Region " + allocation.regionTop.name + " " + allocation.regionTop.weight.toFixed(1) + " %");
    if (!allocation.sectorTop && !allocation.regionTop) reasons.push(allocation.note);
    reasons.push(dividend.note);
    if (share !== null) {
      if (share < targetShare * 0.85) reasons.push("aktuell unter Sollgewicht " + targetShare.toFixed(1) + " %");
      else if (share > targetShare * 1.20) reasons.push("aktuell über Sollgewicht " + targetShare.toFixed(1) + " %");
      else reasons.push("aktuell nahe Sollgewicht " + targetShare.toFixed(1) + " %");
    }
    reasons.push("Stufe " + TIER_LABELS[tier] + (tier === "satellite" ? " (Qualität " + Math.round(bq.q * 100) + "/100" + (bq.pe !== null ? ", KGV " + fmtR1(bq.pe) : "") + ")" : ""));
    const ri = retirementInfo(state);
    if (ri) reasons.push("Ruhestand: " + ri.label + " — Dividende/Stabilität höher gewichtet");
    if (profile === "diversified") reasons.push("Diversiv: Regionen/Sektoren zählen am stärksten");
    else if (profile === "growth") reasons.push("Gewinnoptimierung: Kurserwartung und Kursverlauf zählen am stärksten");
    else if (profile === "buffett") reasons.push("Buffett: Qualität zum fairen Preis (KGV, langfristige Rendite, Dividende) zählt am stärksten, kurzfristige Kursschwankungen kaum");
    else if (profile === "safety") reasons.push("Sicherheit: Streuung, stabiler Kursverlauf und Ausschüttungen stärker gewichtet");

    let confidence = 0;
    if (course.parts >= 2) confidence++;
    if (expected.parts >= 2) confidence++;
    if (allocation.sectorNorm !== null) confidence++;
    if (allocation.regionNorm !== null) confidence++;
    if (dividend.yieldPct !== null || (!isStock(etf) && distributionType(etf) === "accumulating")) confidence++;
    const confidenceLabel = confidence >= 4 ? "hoch" : confidence >= 2 ? "mittel" : "niedrig";

    return {
      etf: etf, score: score, label: label, value: value, share: share, targetShare: targetShare,
      course: course, expected: expected, allocation: allocation, dividend: dividend,
      distribution: isStock(etf) ? "Einzelaktie" : distributionLabel(etf, false),
      confidence: confidenceLabel, dataStatus: dataStatus,
      profile: allocationProfileLabel(state), reasons: reasons,
      tier: tier, tierLabel: TIER_LABELS[tier], quality: bq,
      components: {
        course: Math.round(course.norm * 100), expected: Math.round(expectedNorm * 100),
        allocation: Math.round(allocation.norm * 100), dividend: Math.round(dividend.norm * 100),
        quality: weights.quality ? Math.round(bq.q * 100) : null,
      },
    };
  }).sort(function (a, b) {
    if (a.score === null && b.score === null) return 0;
    if (a.score === null) return 1;
    if (b.score === null) return -1;
    return b.score - a.score;
  });
  rows.reserveCash = resCash > 0 && valueTotal > 0 ? {
    value: resCash, share: resCash / valueTotal * 100, targetShare: tgt.cashShare,
    names: reserveAccounts(state).map(function (x) { return x.name; }),
  } : null;
  return rows;
}

function recommendationHtml(rows, state, ampelByWkn, plan) {
  if (!rows.length) return "<p class='hint'>Noch keine Positionen vorhanden.</p>";
  ampelByWkn = ampelByWkn || {};
  const scored = rows.filter(function (r) { return r.score !== null; });
  // Reihenfolge wie im Sparplan: erst Titel mit Rate (nach Rang), dann Rest nach Score.
  if (plan) {
    const pk = function (r) { const x = plan.index["w:" + r.etf.wkn]; return x && x.rank ? x.rank : 999; };
    scored.sort(function (a, b) { return pk(a) - pk(b) || b.score - a.score; });
  }
  const open = rows.filter(function (r) { return r.score === null; });
  const signed1 = function (v, suffix) { return v === null || !validNumber(v) ? "–" : (v > 0 ? "+" : (v < 0 ? "−" : "")) + fmtR1(Math.abs(v)) + (suffix || ""); };
  const bar = function (label, v) {
    const w = validNumber(v) ? Math.max(0, Math.min(100, v)) : 0;
    return '<div class="fb"><span>' + label + '</span><i><em style="width:' + w + '%"></em></i><b>' + (validNumber(v) ? v : "–") + '</b></div>';
  };
  /* Eine gemeinsame Aussage aus Sparplan (Wie viel? Gewicht/Soll) und Einstiegs-Ampel (Wann? Kurs). */
  function planLabel(r, amp) {
    if (!plan) return r.label;
    const x = plan.index["w:" + r.etf.wkn];
    if (!x) return r.label;
    const green = amp && amp.light === "🟢", red = amp && amp.light === "🔴";
    const why = x.reason ? x.reason.replace(/ — .*$/, "") : "Gewicht ausreichend";
    if (x.rate > 0) return "🟢 Aufstocken (Sparplan #" + x.rank + ")" + (green ? " — Kurs gerade günstig, Einzelkauf lohnt" : (red ? " — Einzelkauf erst nach Rücksetzer, Sparplan weiterlaufen lassen" : ""));
    return green ? "🟡 Halten — Kurs zwar günstig, aber " + why + "; nur kaufen, wenn du diese Position bewusst ausbauen willst"
      : "🟡 Halten — nicht aufstocken (" + why + ")";
  }
  const cards = scored.map(function (r, i) {
    const e = r.etf;
    const dividendText = r.dividend.yieldPct !== null
      ? fmtR2(r.dividend.yieldPct) + " %" + (validNumber(r.dividend.incomeEur) ? " · " + fmtEur(r.dividend.incomeEur) + "/J." : "")
      : (!isStock(e) && distributionType(e) === "accumulating" ? "thesauriert" : "–");
    const diff = r.share !== null ? r.share - r.targetShare : null;
    const amp = ampelByWkn[e.wkn] || null;
    return '<div class="rec' + (r.tier === "core" ? " is-core" : "") + '">' +
      '<div class="recTop"><div><span class="recRank">#' + (i + 1) + '</span><b>' + esc(e.name) + '</b>' +
      '<div class="recKind">' + idsHtml(state, e.wkn) + '</div><div class="recKind">' + isinChip(displayIsin(state, e.wkn)) + '</div><div class="recKind">' + esc(r.distribution) + ' · ' + tierChipHtml(r.tier) + ' · ' + esc(r.profile) + ' · Datenbasis ' + r.confidence + '</div></div>' +
      '<div class="recScore">' + r.score + '<small>/100</small></div></div>' +
      '<div class="recLabel">' + esc(planLabel(r, amp)) + (amp ? '<span class="ampel">' + amp.light + ' Einstieg (Kurs): ' + esc(amp.label) + '</span>' : '') + '</div>' +
      planBadge(plan, "w:" + e.wkn) +
      (r.dataStatus && r.dataStatus.missing.length ? '<div class="dataWarn"><b>Fehlende Daten:</b> ' + esc(r.dataStatus.missing.join(", ")) + '</div>' : '') +
      '<div class="recGrid">' +
      '<div><span>Depotgewicht</span><b>' + (r.share !== null ? fmtR1(r.share) + " %" : "–") + '</b></div>' +
      '<div><span>Sollgewicht</span><b>' + fmtR1(r.targetShare) + ' %</b></div>' +
      '<div><span>Abweichung</span><b class="' + (diff === null ? "" : (diff < 0 ? "good" : "warm")) + '">' + signed1(diff, " Pkt.") + '</b></div>' +
      '<div><span>Kursverlauf 1M–1J</span><b>' + signed1(r.course.trend, " %") + '</b></div>' +
      '<div><span>Erwartete Rendite*</span><b>' + signed1(r.expected.value, " % p. a.") + '</b></div>' +
      '<div><span>Dividende 12 M</span><b>' + dividendText + '</b></div>' +
      '</div>' +
      '<div class="factorBars">' + bar("Kurs", r.components.course) + bar("Erwartung", r.components.expected) +
      bar("Streuung", r.components.allocation) + bar("Dividende", r.components.dividend) +
      (r.components.quality !== null && r.components.quality !== undefined ? bar("Qualität", r.components.quality) : "") +
      '</div>' +
      '<div class="recWhy"><b>Warum:</b> ' + esc(r.reasons.join(" · ")) + '</div>' +
      (amp ? '<details class="ampFold"><summary>Bewertung &amp; Technik (Ampel)</summary>' + amp.body + '</details>' : '') +
      '</div>';
  }).join("");
  const rest = open.length
    ? '<h3 class="miniHead">Ohne Empfehlung (' + open.length + ')</h3>' + open.map(function (r) {
        const miss = r.dataStatus && r.dataStatus.missing.length ? r.dataStatus.missing.join(", ") : "Pflichtdaten fehlen";
        return '<div class="recMini"><b>' + esc(r.etf.name) + '</b><span>' + esc(displayIds(state, r.etf.wkn)) + '</span><small>Fehlt: ' + esc(miss) + '</small></div>';
      }).join("")
    : "";
  return (cards || "<p class='hint'>Für keine Position liegen alle Pflichtdaten vor.</p>") + rest;
}

/* ============================================================================
 * Verkaufsempfehlungen (Reduzieren / Verkaufen) — Gegenstück zu den Kaufprioritäten.
 * Bewusst einfache, offen gelegte Punkte-Regeln (wie die Einstiegs-Ampel):
 *  ✗ Verkaufsargument = +Punkte · ✓ Argument fürs Halten = −Punkte
 * Genutzt werden ausschließlich bereits vorhandene Größen: Aufstockungs-Score,
 * Depot-/Sollgewicht, Kursverlauf, Kurserwartung, Technik (RSI, 200-Tage-Linie),
 * KGV und Überschneidung. Fehlt ein Wert, fällt nur diese Regel weg (nichts wird
 * geschätzt). Ohne vollständige Pflichtdaten (wie bei „Aufstocken“) keine Empfehlung.
 * Steuern, Gebühren und Sperrfristen: Sperrfrist-Stücke werden als nicht verkaufbar
 * ausgewiesen; Steuern/Gebühren sind NICHT berücksichtigt.
 * ==========================================================================*/

function sellLockedQty(state, wkn) {
  const now = Date.now();
  let locked = 0, until = null;
  state.positions.forEach(function (p) {
    if (p.wkn !== wkn || !p.lockDate) return;
    const t = new Date(p.lockDate).getTime();
    if (!isFinite(t) || t <= now) return;
    locked += p.qty;
    if (until === null || t > until) until = t;
  });
  return { qty: locked, until: until };
}

function sellAnalysis(state, recRows) {
  const mfByWkn = {};
  buildMarketFunds(state).forEach(function (f) { mfByWkn[f.wkn] = f; });
  const kzByWkn = {};
  try {
    buildKennzahlenModel(state).funds.forEach(function (f) { kzByWkn[f.wkn] = f; });
  } catch (e) {
    logEvent("FEHLER", "Verkaufsempfehlung", "Kennzahlen (KGV/Technik) nicht verfügbar: " + errText(e));
  }
  const totalValue = recTotalValue(recRows);   // inkl. 🏦 Tagesgeld (Anteile beziehen sich darauf)
  const SS = strategyParams(state).sell, stratLbl = allocationProfileLabel(state);

  return recRows.map(function (r) {
    const e = r.etf;
    const kz = kzByWkn[e.wkn] || null;
    const mf = mfByWkn[e.wkn] || null;
    const tc = kz && kz.tech ? kz.tech : null;
    let pts = 0;
    const why = [];
    function add(p, icon, text) { pts += p; why.push({ i: icon, t: text }); }
    // Kursschwäche (Abwärtstrend, schwacher Kursverlauf, negative Kurserwartung) beschreibt EIN Signal —
    // sie zählt zusammen höchstens +1 (der Aufstockungs-Score enthält sie ohnehin schon).
    let weakCounted = false;
    function addWeak(text) {
      if (!weakCounted) { weakCounted = true; add(1, "✗", text + " (Kursschwäche, zählt einmal)"); }
      else why.push({ i: "✗", t: text + " (bereits als Kursschwäche gezählt)" });
    }

    // 1) Depotgewicht gegen Sollgewicht
    if (r.share !== null && r.targetShare > 0) {
      const ratio = r.share / r.targetShare;
      const base = "Depotgewicht " + fmtR1(r.share) + " % · Soll " + fmtR1(r.targetShare) + " % (" + r.tierLabel + ")";
      if (r.tier === "core" || r.tier === "reserve") {
        // Kern/Reserve nicht aktiv verkaufen — Übergewicht über Zukäufe der anderen Stufen ausgleichen.
        if (ratio >= 1.5) add(1, "✗", base + " – deutlich darüber, Zukäufe umlenken statt verkaufen");
        else if (ratio <= 0.85) add(-1, "✓", base + " – darunter");
        else why.push({ i: "•", t: base + (ratio >= 1.2 ? " – darüber, über Zukäufe ausgleichen" : " – nahe Soll") });
      } else {
        if (ratio >= SS.hi) add(2, "✗", base + " – deutlich darüber");
        else if (ratio >= SS.mid) add(1, "✗", base + " – darüber");
        else if (ratio <= 0.85) add(-1, "✓", base + " – darunter");
        else why.push({ i: "•", t: base + " – nahe Soll" });
      }
    }
    // 2) Aufstockungs-Score
    if (r.score !== null) {
      if (r.score < 30) add(2, "✗", "Aufstockungs-Score " + r.score + "/100 – derzeit nicht aufstocken");
      else if (r.score < 45) add(1, "✗", "Aufstockungs-Score " + r.score + "/100 – nur Halten");
      else if (r.score >= 60) add(-2, "✓", "Aufstockungs-Score " + r.score + "/100 – spricht fürs Halten/Aufstocken");
      else why.push({ i: "•", t: "Aufstockungs-Score " + r.score + "/100 – neutral" });
    }
    // 3) Technik (Strategie Buffett: kurzfristige Kursbewegungen zählen nicht)
    if (tc && !SS.tech) why.push({ i: "•", t: "Technik nicht gewertet — Strategie " + stratLbl + " ignoriert kurzfristige Kursbewegungen" });
    if (tc && SS.tech) {
      let tp = 0;
      const bits = [];
      if (validNumber(tc.rsi) && tc.rsi >= 70) { tp += 1; bits.push("überkauft (RSI " + Math.round(tc.rsi) + ")"); }
      if (tc.trend === "up" && !(validNumber(tc.rsi) && tc.rsi >= 70)) { tp -= 1; bits.push("Aufwärtstrend"); }
      if (bits.length || tc.trend !== "down") add(tp, tp > 0 ? "✗" : (tp < 0 ? "✓" : "•"), "Technik: " + (bits.join(", ") || "keine Auffälligkeit"));
      if (tc.trend === "down") addWeak("Technik: Abwärtstrend, unter 200-Tage-Linie");
    }
    // 4) Kursverlauf 1M–1J
    if (r.course.trend !== null) {
      if (r.course.trend <= -10 && SS.course) addWeak("Kursverlauf " + fmtSigned(r.course.trend, 1) + " (1M–1J gewichtet) – schwach");
      else why.push({ i: "•", t: "Kursverlauf " + fmtSigned(r.course.trend, 1) + " (1M–1J gewichtet)" });
    }
    // 5) Historisch abgeleitete Kurserwartung
    if (r.expected.value !== null) {
      const ex = "Kurserwartung ca. " + fmtSigned(r.expected.value, 1) + " p.a.";
      if (r.expected.value < 0) addWeak(ex + " – negativ");
      else if (r.expected.value >= 8) add(-1, "✓", ex + " – solide");
      else why.push({ i: "•", t: ex });
    }
    // 6) Bewertung (KGV)
    if (kz && validNumber(kz.pe)) {
      const b = peBand(kz.pe);
      const t = "KGV " + fmtR1(kz.pe) + " – " + (b ? b.label : "");
      if (kz.pe > SS.peSell) add(1, "✗", t + " (Grenze " + SS.peSell + " bei " + stratLbl + ")");
      else if (kz.pe < SS.peHold) add(-1, "✓", t);
      else why.push({ i: "•", t: t });
    }
    // 7) Überschneidung mit dem Rest-Depot
    if (kz && kz.overlap) {
      const o = kz.overlap.pct;
      const t = "Überschneidung mit dem Rest-Depot " + Math.round(o) + " %";
      if (o >= SS.overlap) add(1, "✗", t + " – vieles hast du schon");
      else why.push({ i: "•", t: t });
    }

    // 8) Höhe der Dividende: hohe Ausschüttung spricht fürs Halten
    const dvm = r.dividend;
    if (dvm && dvm.yieldPct !== null) {
      const t = "Dividende " + fmtR2(dvm.yieldPct) + " %" + (validNumber(dvm.incomeEur) ? " · " + fmtEur(dvm.incomeEur) + "/Jahr" : "") +
        (validNumber(dvm.sharePct) ? " · " + fmtR1(dvm.sharePct) + " % der Depot-Dividenden" : "");
      let dp = 0;
      if (dvm.yieldPct >= 3 && SS.divHold) dp -= 1;
      if (validNumber(dvm.sharePct) && dvm.sharePct >= 20) dp -= 1;
      if (dp < 0) add(dp, "✓", t + " – Verkauf kostet Ausschüttung");
      else if (validNumber(dvm.depotYieldPct) && dvm.yieldPct < dvm.depotYieldPct * 0.5 && dvm.yieldPct < 1) add(1, "✗", t + " – deutlich unter Depot-Ø " + fmtR2(dvm.depotYieldPct) + " %");
      else why.push({ i: "•", t: t });
    } else if (dvm) {
      why.push({ i: "•", t: "Dividende: " + dvm.note });
    }

    // 8b) Strategie: Qualität (Buffett) bzw. Schwankung (Sicherheit)
    if (SS.quality && r.quality && validNumber(r.quality.q) && r.tier === "satellite") {
      if (r.quality.q >= 0.65) add(-1, "✓", "Qualität " + Math.round(r.quality.q * 100) + "/100 — gutes Unternehmen langfristig halten (" + stratLbl + ")");
      else if (r.quality.q < 0.4) add(1, "✗", "Qualität nur " + Math.round(r.quality.q * 100) + "/100 — passt nicht zur Strategie " + stratLbl);
    }
    if (SS.drawdown !== null && r.tier === "satellite" && r.course && r.course.maxDrawdown !== null && r.course.maxDrawdown <= SS.drawdown) {
      add(1, "✗", "max. Rückgang 1J " + fmtR1(r.course.maxDrawdown) + " % — zu schwankungsreich für die Strategie " + stratLbl);
    }
    // 9) Ruhestand: starke Schwankung kurz vor Rentenbeginn
    const rti = retirementInfo(state);
    if (rti && r.tier !== "reserve" && r.course && r.course.maxDrawdown !== null && r.course.maxDrawdown <= -25) {
      if (rti.years <= 5 && r.tier === "satellite") add(1, "✗", "max. Rückgang 1J " + fmtR1(r.course.maxDrawdown) + " % – hohes Schwankungsrisiko, " + rti.label);
      else why.push({ i: "•", t: "max. Rückgang 1J " + fmtR1(r.course.maxDrawdown) + " % – " + rti.label });
    }
    if (rti && lockAfterRetire(state, e.wkn, rti)) why.push({ i: "•", t: "Sperrfrist reicht über den Rentenbeginn hinaus" });

    // Kern/Reserve werden nicht aktiv verkauft: höchstens „Beobachten“, Übergewicht über Zukäufe ausgleichen.
    const protectedTier = r.tier === "core" || r.tier === "reserve";
    if (protectedTier && pts > 2) {
      why.push({ i: "•", t: TIER_LABELS[r.tier] + ": kein aktiver Verkauf — " + pts + " Punkte auf 2 begrenzt; Zukäufe auf andere Positionen lenken" });
      pts = 2;
    }

    // Einordnung
    let light = "🟢", label = "Halten";
    if (r.score === null) { light = "⚠️"; label = "Daten unvollständig – keine Empfehlung"; }
    else if (pts >= 5) { light = "🔴"; label = "Reduzieren prüfen"; }
    else if (pts >= 3) { light = "🟠"; label = "Teilverkauf prüfen"; }
    else if (pts >= 1) { light = "🟡"; label = "Beobachten"; }

    // Abbau bis Sollgewicht (nur bei Übergewicht) — Sperrfrist-Stücke ausgenommen
    const price = currentMarketPrice(e);
    const lock = sellLockedQty(state, e.wkn);
    const freeQty = Math.max(0, (e.amount || 0) - lock.qty);
    let reduce = null;
    if (!protectedTier && r.score !== null && r.share !== null && r.value !== null && totalValue > 0 && r.share > r.targetShare * 1.2 && validNumber(price) && price > 0) {
      const overEur = r.value - r.targetShare / 100 * totalValue;
      if (overEur > 0) {
        let qty = overEur / price;
        const capped = qty > freeQty;
        if (capped) qty = freeQty;
        qty = Math.floor(qty * 100 + 1e-9) / 100;   // abrunden — nie mehr als die freien Stücke
        reduce = { eur: qty * price, qty: qty, capped: capped, fullEur: overEur };
      }
    }
    const perf = mf ? marketPurchasePerformance(mf) : null;

    return {
      etf: e, row: r, pts: pts, light: light, label: label, why: why, reduce: reduce, perf: perf,
      lock: lock, freeQty: freeQty, price: price,
      overRatio: (r.share !== null && r.targetShare > 0) ? r.share / r.targetShare : 0,
    };
  }).sort(function (a, b) {
    const an = a.row.score === null, bn = b.row.score === null;
    if (an && bn) return 0;
    if (an) return 1;
    if (bn) return -1;
    if (b.pts !== a.pts) return b.pts - a.pts;
    return b.overRatio - a.overRatio;
  });
}

function lockAfterRetire(state, wkn, rti) {
  return state.positions.some(function (p) { return p.wkn === wkn && p.lockDate && new Date(p.lockDate).getTime() > rti.date.getTime(); });
}

function sellSectionHtml(rows, state) {
  if (!rows.length) return "<p class='hint'>Noch keine Positionen vorhanden.</p>";
  const red = rows.filter(function (x) { return x.light === "🔴"; }).length;
  const orange = rows.filter(function (x) { return x.light === "🟠"; }).length;
  const summary = "<p class='meta'>" + (red ? "🔴 " + red + " · " : "") + (orange ? "🟠 " + orange + " · " : "") +
    (red + orange === 0 ? "Aktuell keine Position mit deutlichem Verkaufsdruck." : "Positionen mit erhöhtem Verkaufsdruck.") + "</p>";
  const active = rows.filter(function (x) { return x.row.score !== null && x.pts >= 1; });
  const hold = rows.filter(function (x) { return x.row.score !== null && x.pts < 1; });
  const cards = active.map(function (x, i) {
    const e = x.etf, r = x.row;
    const scoreText = r.score === null ? "–" : (x.pts > 0 ? "+" : (x.pts < 0 ? "−" : "")) + Math.abs(x.pts);
    let reduceText = "–";
    if (x.reduce) reduceText = "≈ " + fmtEur(x.reduce.eur) + " (" + fmtQty(x.reduce.qty) + " Stk.)";
    else if (r.tier === "core" || r.tier === "reserve") reduceText = "kein Verkauf (" + r.tierLabel + ") — über Zukäufe ausgleichen";
    else if (r.score !== null && x.overRatio > 0 && x.overRatio <= 1.2) reduceText = "nicht nötig";
    const lockText = x.lock.qty > 0
      ? fmtQty(x.lock.qty) + " Stk. gesperrt bis " + new Date(x.lock.until).toLocaleDateString("de-DE")
      : "keine";
    return '<div class="rec' + (r.tier === "core" ? " is-core" : "") + '">' +
      '<div class="recTop"><div><span class="recRank">#' + (i + 1) + '</span><b>' + esc(e.name) + '</b>' +
      '<div class="recKind">' + idsHtml(state, e.wkn) + '</div><div class="recKind">' + esc(r.distribution) + ' · ' + tierChipHtml(r.tier) + ' · ' + esc(r.profile) + '</div></div>' +
      '<div class="recScore">' + scoreText + '<small>' + (r.score === null ? '' : ' Pkt.') + '</small></div></div>' +
      '<div class="recLabel">' + x.light + ' ' + esc(x.label) + '</div>' +
      (r.dataStatus && r.dataStatus.missing.length ? '<div class="dataWarn"><b>Fehlende Daten:</b> ' + esc(r.dataStatus.missing.join(", ")) + '</div>' : '') +
      '<div class="recGrid">' +
      '<div><span>Depotgewicht / Soll</span><b>' + (r.share !== null ? fmtR1(r.share) + " %" : "–") + ' / ' + fmtR1(r.targetShare) + ' %</b></div>' +
      '<div><span>Abbau bis Sollgewicht</span><b>' + esc(reduceText) + '</b></div>' +
      '<div><span>Sperrfrist</span><b>' + esc(lockText) + '</b></div>' +
      '</div>' +
      (x.reduce && x.reduce.capped ? '<div class="dataWarn">Wegen der Sperrfrist ist nur ein Teil des Übergewichts verkaufbar (voller Abbau: ≈ ' + esc(fmtEur(x.reduce.fullEur)) + ').</div>' : '') +
      '<div class="recWhy">' + x.why.map(function (w) { return esc(w.i + " " + w.t); }).join("<br>") + '</div>' +
      '</div>';
  }).join("");
  const holdLine = hold.length
    ? '<div class="recMini hold"><b>🟢 Halten (' + hold.length + ')</b><small>' + esc(hold.map(function (x) { return x.etf.name; }).join(" · ")) + '</small></div>'
    : "";
  return summary + cards + holdLine;
}

/* ============================================================================
 * Neue Kaufideen (⚙️ zuschaltbar): nicht gehaltene ETFs/Aktien, die
 * nach der Kern/Satellit/Reserve-Staffelung zum Depot passen. Quellen je Depot: KI-Recherche und ETF-Bestände,
 * bewertet gegen Lücken im Depot (fehlende Stufe, Region, Sektor, Dividende),
 * Qualität und Doppelung über ETF-Bestände. Keine Kurs-/Score-Abfrage
 * der Kandidaten — Orientierung, keine Anlageberatung.
 * ==========================================================================*/
// Keine fest eingetragenen Kandidaten mehr (v2.79): Kaufideen stammen ausschließlich aus der
// Recherche je Depot — 🤖 KI-Vorschläge und 📦 Kandidaten aus den eigenen ETFs.
const BUY_IDEA_CANDIDATES = [];

/* Geheimtipp-Muster aus 5 Jahren Wochenkursen: langfristig stetig steigend
 * (≥ 6 % p. a., mind. 4 von 5 Jahresabschnitten im Plus), aktuell im Rücksetzer
 * (≥ 10 % unter 52W-Hoch oder ≥ 3 % unter der 40-Wochen-Linie ≈ 200 Tage). */
function tipMetrics(points) {
  if (!points || points.length < 150) return null;
  const pts = points.slice().sort(function (a, b) { return a.t - b.t; });
  const first = pts[0], last = pts[pts.length - 1];
  const years = (last.t - first.t) / (365.25 * 86400000);
  if (years < 3.5 || !(first.c > 0)) return null;
  const cagr = (Math.pow(last.c / first.c, 1 / years) - 1) * 100;
  let up = 0, segs = 0;
  for (let k = 0; k < Math.floor(years); k++) {
    const a = pts[Math.floor(k / years * (pts.length - 1))], b = pts[Math.floor((k + 1) / years * (pts.length - 1))];
    if (a && b) { segs++; if (b.c > a.c) up++; }
  }
  const yearAgo = last.t - 365 * 86400000;
  const high = Math.max.apply(null, pts.filter(function (p) { return p.t >= yearAgo; }).map(function (p) { return p.c; }));
  const dd = (last.c / high - 1) * 100;
  const tail = pts.slice(-40);
  const sma = tail.reduce(function (s, p) { return s + p.c; }, 0) / tail.length;
  const vsSma = (last.c / sma - 1) * 100;
  const tip = cagr >= 6 && segs >= 4 && up >= segs - 1 && (dd <= -10 || vsSma <= -3);
  const yr = pts.filter(function (p) { return p.t >= yearAgo; }).map(function (p) { return p.c; });
  const low = Math.min.apply(null, yr);
  const pos52 = high > low ? (last.c - low) / (high - low) * 100 : 50;
  return { cagr: cagr, up: up, segs: segs, dd: dd, vsSma: vsSma, tip: tip, last: last.c, sma: sma, high: high, low: low, pos52: pos52 };
}

/* Kaufkurs-Einschätzung aus Kurs vs. 200-Tage-Linie (40 Wochen) und Lage in der
 * 52-Wochen-Spanne. Empfohlener Kaufkurs (Limit): günstig → aktueller Kurs; fair → knapp
 * darunter; erhöht/teuer → 200-Tage-Linie (auf Rücksetzer warten). „Bis zu“ = Linie + 3 %. */
function buyPriceAdvice(trend) {
  if (!trend || !validNumber(trend.sma) || !validNumber(trend.last)) return null;
  const v = trend.vsSma, pos = trend.pos52;
  let light, label, limit, note;
  const longUp = validNumber(trend.cagr) && trend.cagr > 0 && (!validNumber(trend.segs) || !trend.segs || trend.up >= Math.ceil(trend.segs / 2));
  if ((v <= -3 || trend.dd <= -12) && longUp) {
    // Rücksetzer nur dann „günstig“, wenn der Langfristtrend (5 J) intakt ist — sonst fallendes Messer.
    light = "🟢"; label = "Rücksetzer im Aufwärtstrend — Kauf lohnenswert"; limit = trend.last;
    note = fmtR1(Math.abs(v)) + " % unter 200-Tage-Linie, " + fmtR1(Math.abs(trend.dd)) + " % unter 52W-Hoch, 5 J " + fmtSigned(trend.cagr, 1) + " p. a.";
  } else if (v <= -3 || trend.dd <= -12) {
    light = "🟠"; label = "fällt — Bodenbildung abwarten"; limit = trend.last * 0.95;
    note = fmtR1(Math.abs(v)) + " % unter 200-Tage-Linie" + (validNumber(trend.cagr) ? "" : ", Langfristtrend unbekannt");
  } else if (v <= 4 && pos <= 75) {
    light = "🟡"; label = "fairer Preis"; limit = trend.last * 0.99;
    note = "nahe 200-Tage-Linie (" + fmtSigned(v, 1) + "), " + Math.round(pos) + " % der 52W-Spanne";
  } else if (v <= 10) {
    light = "🟠"; label = "erhöht — mit Limit kaufen"; limit = trend.sma;
    note = fmtSigned(v, 1) + " über 200-Tage-Linie, " + Math.round(pos) + " % der 52W-Spanne";
  } else {
    light = "🔴"; label = "teuer — Rücksetzer abwarten"; limit = trend.sma;
    note = fmtSigned(v, 1) + " über 200-Tage-Linie, nahe 52W-Hoch (" + fmtR1(Math.abs(trend.dd)) + " % darunter)";
  }
  if (light === "🟠" && !/^fällt/.test(label) && trend.last <= trend.sma * 1.03) label = "leicht erhöht — Kauf vertretbar, besser mit Limit";
  if (validNumber(trend.cagr) && trend.cagr < 0) note += " · Langfristtrend negativ (" + fmtSigned(trend.cagr, 1) + " p. a.)";
  return { light: light, label: label, limit: limit, max: trend.sma * 1.03, note: note };
}

/* ===========================================================================
 * 🤖 KI-Vorschläge. Claude über die Anthropic-API (Messages-Endpunkt) mit dem
 * Websuche-Tool. Liefert Kandidaten (ISIN, Name, Art, Sektor, Begründung) als JSON; die App
 * prüft ISIN-Prüfziffer, Doppelungen und Bestand und behandelt sie danach wie alle anderen
 * Kaufideen (Dividende, Trend, Bewertung, Überschneidung). Abruf höchstens alle 30 Tage
 * automatisch (oder manuell in ⚙️). Kosten trägt das eigene API-Guthaben.
 * =========================================================================*/
const AI_KEYCHAIN_KEY = APP.name + ".anthropic-key";
const AI_MODELS = ["claude-sonnet-5-5", "claude-sonnet-4-6"];   // erstes verfügbares Modell wird genutzt
const AI_REFRESH_DAYS = 30, AI_EXPIRE_DAYS = 90, AI_MAX = 12;

function aiKey() { try { return Keychain.contains(AI_KEYCHAIN_KEY) ? String(Keychain.get(AI_KEYCHAIN_KEY) || "").trim() : ""; } catch (e) { return ""; } }
function aiOn(state) { return !!(state && state.settings && state.settings.ai === true); }

function isinValid(isin) {
  const v = String(isin || "").toUpperCase();
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(v)) return false;
  const digits = v.slice(0, 11).split("").map(function (ch) { return parseInt(ch, 36); }).join("");
  let sum = 0;
  digits.split("").reverse().forEach(function (d, i) { let n = Number(d); if (i % 2 === 0) { n *= 2; if (n > 9) n -= 9; } sum += n; });
  return (10 - sum % 10) % 10 === Number(v[11]);
}

/* Aktive KI-Kandidaten im Format der Kandidatenliste. */
function aiCandidates(state) {
  if (!aiOn(state) || !state.aiIdeas || !Array.isArray(state.aiIdeas.items)) return [];
  const cut = Date.now() - AI_EXPIRE_DAYS * 86400000;
  return state.aiIdeas.items.filter(function (x) { return new Date(x.lastSeen).getTime() >= cut; }).map(function (x) {
    const etf = x.kind === "etf";
    // Kategorie aus der Recherche hat Vorrang vor der Namenserkennung
    // Stufe aus Kennzahlen (Kurshistorie der Kaufidee); ohne Daten Kategorie der Recherche, zuletzt Name.
    const bp = state.buyIdeaPrices && state.buyIdeaPrices[String(x.isin || "").toUpperCase()];
    const as = etf ? tierAssess({ wkn: x.isin, name: x.name, kind: "fund", mkt: bp && bp.trend && bp.trend.mkt || null }, state) : null;
    const tier = !etf ? "satellite" : (as.basis !== "name" ? as.tier : (x.cat === "kern" ? "core" : (x.cat === "reserve" ? "reserve" : as.tier)));
    return { isin: x.isin, name: x.name, kind: etf ? "etf" : "stock", tier: tier, sector: x.sector || undefined, cat: x.cat || undefined,
      gap: x.cat === "dividende" && etf ? "dividend" : undefined,
      key: etf ? undefined : stockNameKey(x.name), note: x.reason, ai: true, aiDate: x.lastSeen };
  });
}
/* ===========================================================================
 * 📦 Kandidaten aus den eigenen ETFs. Die größten Unternehmen der Durchschau
 * (nach Depotgewicht) bilden einen sich selbst erneuernden Pool. Kurs/Dividende/Historie
 * werden höchstens wöchentlich geladen. Angezeigt wird ein Pool-Titel nur, wenn er
 * Dividende zahlt, gerade günstig ist (Kaufkurs-Ampel 🟢) oder das Geheimtipp-Muster zeigt
 * und über die ETFs noch unter 3 % des Depots ausmacht.
 * =========================================================================*/
const POOL_MAX = 40, POOL_REFRESH_DAYS = 7, POOL_MAX_INDIRECT = 3;

function poolOn(state) { return !(state && state.settings && state.settings.poolIdeas === false); }

function poolCandidates(state) {
  if (!buyIdeasOn(state) || !poolOn(state)) return [];
  let etfs;
  try { etfs = buildOverviewEtfs(state); } catch (e) { return []; }
  const isinByKey = {};
  etfs.forEach(function (e) { (e.holdings || []).forEach(function (h) { const k = holdingKey(h); if (h.isin && !isinByKey[k]) isinByKey[k] = String(h.isin).toUpperCase(); }); });
  const fund = (state.overview && state.overview.fundamentals && state.overview.fundamentals.items) || {};
  // Durchschau über das ganze Depot (Anteile relativ zum Gesamtwert), aber nur Titel, die über ETFs gehalten werden
  const stockNames = {};
  etfs.forEach(function (e) { if (e.kind === "stock") stockNames[e.name] = true; });
  const out = [];
  lookThrough({ etfs: etfs }).forEach(function (x) {
    if (out.length >= POOL_MAX) return;
    const viaFunds = x.via.filter(function (v) { return !stockNames[v.etf]; });
    if (!viaFunds.length || viaFunds.length < x.via.length) return;   // direkt gehaltene Aktien überspringen
    x = { name: x.name, pct: x.pct, via: viaFunds };
    const k = holdingKey(x);
    const f = fund[k] || {};
    const isin = isinValid(isinByKey[k] || f.isin) ? String(isinByKey[k] || f.isin).toUpperCase() : null;
    const sym = f.symbol || null;
    if (!isin && !sym) return;   // ohne ISIN/Symbol nicht abrufbar
    out.push({ isin: isin || ("SYM:" + sym), name: x.name, kind: "stock", tier: "satellite", key: stockNameKey(x.name),
      sector: f.sector || undefined, syms: sym ? [sym] : undefined, pool: true, poolPct: x.pct,
      note: "aus deinen ETFs (" + x.via.slice(0, 2).map(function (v) { return v.etf; }).join(", ") + (x.via.length > 2 ? " u. a." : "") + "), dort indirekt " + fmtR1(x.pct) + " % des Depots" });
  });
  return out;
}

function allBuyCandidates(state) {
  const seen = {};
  return BUY_IDEA_CANDIDATES.concat(aiCandidates(state)).concat(poolCandidates(state)).filter(function (c) {
    if (seen[c.isin]) return false; seen[c.isin] = true; return true;
  });
}

function aiDepotBrief(state) {
  let rows = [];
  try { rows = recommendationAnalysis(state); } catch (e) { rows = []; }
  const total = rows.reduce(function (s, r) { return s + (r.value || 0); }, 0);
  const rcA = recReserveCash(rows);
  const lines = rows.map(function (r) {
    return "- " + r.etf.name + " (" + displayIsin(state, r.etf.wkn) + ", " + (isStock(r.etf) ? "Aktie" : "ETF") + ", " + (r.tierLabel || "") +
      ", Anteil " + (validNumber(r.share) ? fmtR1(r.share) : "–") + " %" + (r.dividend && r.dividend.yieldPct !== null ? ", Dividende " + fmtR2(r.dividend.yieldPct) + " %" : "") + ")";
  });
  let sectors = "", countries = "";
  try {
    const ov = computeOverview(state);
    sectors = ov.sectorOverview.rows.slice(0, 8).map(function (x) { return x.name + " " + fmtR1(x.pct) + " %"; }).join(", ");
    countries = ov.countryOverview.rows.slice(0, 8).map(function (x) { return x.name + " " + fmtR1(x.pct) + " %"; }).join(", ");
  } catch (e) { /* ohne Durchschau */ }
  const ri = retirementInfo(state);
  return { total: total, text:
    "Depot (" + rows.length + " Positionen, Gesamtwert ca. " + Math.round(total) + " EUR):\n" + lines.join("\n") +
    (rcA ? "\nReserve zusätzlich: Tagesgeld ca. " + Math.round(rcA.value) + " EUR (" + fmtR1(rcA.share) + " % von Depot + Tagesgeld) — zählt als Reserve, Anteile oben beziehen sich auf Depot + Tagesgeld" : "") +
    (sectors ? "\nSektoren (Durchschau): " + sectors : "") + (countries ? "\nLänder (Durchschau): " + countries : "") +
    "\nStrategie: " + allocationProfileLabel(state) + " — " + (PROFILE_HINTS[allocationProfile(state)] || "") + ". Vorgabe: " + strategyParams(state).ai +
    (ri ? "\nRuhestand: " + ri.label + " — Stabilität und planbare Dividenden wichtig" : "") +
    (retirementSettings(state).saving ? "\nMonatliche Sparrate: " + retirementSettings(state).saving + " EUR" : "") };
}

async function aiCall(key, body) {
  let lastErr = null;
  for (let i = 0; i < AI_MODELS.length; i++) {
    const req = new Request("https://api.anthropic.com/v1/messages");
    req.method = "POST";
    req.timeoutInterval = 120;
    req.headers = { "content-type": "application/json", "x-api-key": key, "anthropic-version": "2023-06-01" };
    req.body = JSON.stringify(Object.assign({ model: AI_MODELS[i] }, body));
    let json = null;
    try { json = await req.loadJSON(); } catch (e) { lastErr = e; continue; }
    const status = req.response && req.response.statusCode;
    if (json && json.type === "error") {
      const msg = (json.error && (json.error.type + ": " + json.error.message)) || "Fehler";
      // unbekanntes Modell → nächstes probieren; alles andere direkt melden
      if (/model/i.test(msg) && (status === 404 || status === 400 || /not_found/i.test(msg))) { lastErr = new Error(msg); continue; }
      throw new Error("Anthropic-API " + (status || "") + " — " + msg);
    }
    if (json) return { json: json, model: AI_MODELS[i] };
  }
  throw lastErr || new Error("Keine Antwort der Anthropic-API");
}

async function refreshAiIdeas(state, force) {
  if (!aiOn(state)) return false;
  if (isAggregate(state)) return false;   // Recherche erfolgt je Depot; die Gesamtansicht fasst nur zusammen
  const key = aiKey();
  if (!key) { logEvent("WARNUNG", "KI-Vorschläge", "Kein API-Schlüssel hinterlegt (⚙️ → KI-Vorschläge)"); return false; }
  const prev = state.aiIdeas || { items: [] };
  const profNow = allocationProfile(state);
  // Strategie gewechselt → Vorschläge passen nicht mehr: neu recherchieren (sonst höchstens alle AI_REFRESH_DAYS Tage)
  if (!force && prev.fetchedAt && Date.now() - new Date(prev.fetchedAt).getTime() < AI_REFRESH_DAYS * 86400000 && (!prev.profile || prev.profile === profNow)) return false;
  if (MAIN_WV) await setProgress(MAIN_WV, true, "🤖 KI-Vorschläge: Markt- und Weltlage wird recherchiert …", 30);
  const brief = aiDepotBrief(state);
  const known = allBuyCandidates(state).map(function (c) { return c.isin; }).concat(state.positions.map(function (p) { return displayIsin(state, p.wkn); }));
  const prompt =
    "Du unterstützt einen deutschen Privatanleger bei der Auswahl neuer Wertpapiere. Recherchiere mit der Websuche die aktuelle Lage an den Börsen und in der Welt " +
    "(Zinsen, Konjunktur, Geopolitik, Branchentrends) und schlage bis zu " + AI_MAX + " ausschüttende Qualitätsaktien oder ausschüttende ETFs vor, die genau DIESES Depot sinnvoll ergänzen.\n" +
    "Decke dabei — soweit im Depot fehlend oder untergewichtet — ab: kategorie \"kern\" (breiter, günstiger Welt- oder S&P-500-ETF, ausschüttend), \"reserve\" (kurzlaufende Euro-Anleihen oder Geldmarkt, ausschüttend), " +
    "\"region\" (unterrepräsentierte Regionen), \"dividende\" (verlässliche Dividendenzahler), \"qualitaet\" (Qualitätsaktien mit solider Bilanz und vernünftiger Bewertung) und \"geheimtipp\" (über Jahre stetig gestiegen, aktuell im Rücksetzer).\n\n" +
    "Regeln: nur ausschüttende Titel (keine thesaurierenden ETFs, keine Aktien ohne Dividende); Qualitätskriterien (Wettbewerbsvorteil, solide Bilanz, vernünftige Bewertung, langfristig stabile oder steigende Dividende); " +
    "in Deutschland (Xetra/Tradegate) handelbar; Lücken im Depot bei Regionen/Sektoren schließen und keine Titel vorschlagen, die über die ETFs schon stark enthalten sind; " +
    "keine Spekulation, keine Hebelprodukte, keine Kryptowährungen. Richte Auswahl und Gewichtung strikt nach der unten genannten Strategie aus.\n" +
    "Nicht vorschlagen (bereits im Depot oder schon auf der Liste): " + known.join(", ") + "\n\n" + brief.text + "\n\n" +
    "Antworte am Ende ausschließlich mit einem JSON-Array ohne weiteren Text, Format:\n" +
    '[{"isin":"…","name":"…","kind":"stock|etf","kategorie":"kern|reserve|region|dividende|qualitaet|geheimtipp","sector":"…","reason":"max. 200 Zeichen Begründung auf Deutsch mit Bezug zur aktuellen Lage"}]';
  try {
    const res = await aiCall(key, {
      max_tokens: 4000,
      messages: [{ role: "user", content: prompt }],
      tools: [{ type: "web_search_20250305", name: "web_search", max_uses: 5 }],
    });
    const text = (res.json.content || []).filter(function (b) { return b.type === "text"; }).map(function (b) { return b.text; }).join("\n");
    const a = text.lastIndexOf("["), b = text.lastIndexOf("]");
    let arr = [];
    if (a >= 0 && b > a) {
      // letztes JSON-Array mit Objekten („[{ … }]“) aus dem Antworttext lösen
      let start = text.lastIndexOf("[{");
      if (start < 0 || start > b) start = text.lastIndexOf("[", b);
      try { arr = JSON.parse(text.slice(start, b + 1)); }
      catch (e) { try { arr = JSON.parse(text.slice(text.indexOf("["), b + 1)); } catch (e2) { arr = []; } }
    }
    if (!arr.length) logEvent("WARNUNG", "KI-Vorschläge", "Antwort ohne verwertbares JSON: " + text.slice(-300));
    const knownSet = {}; known.forEach(function (k) { knownSet[String(k).toUpperCase()] = true; });
    const now = new Date().toISOString();
    const byIsin = {}; (prev.items || []).forEach(function (x) { byIsin[x.isin] = x; });
    let added = 0, rejected = 0;
    (Array.isArray(arr) ? arr : []).slice(0, AI_MAX).forEach(function (x) {
      const isin = String(x && x.isin || "").toUpperCase().trim();
      if (!isinValid(isin) || (knownSet[isin] && !byIsin[isin])) { rejected++; return; }
      const item = { isin: isin, name: String(x.name || isin).slice(0, 80), kind: x.kind === "etf" ? "etf" : "stock",
        sector: String(x.sector || "").slice(0, 40), reason: String(x.reason || "").slice(0, 240), lastSeen: now,
        cat: String(x.kategorie || x.category || "").toLowerCase().slice(0, 20),
        firstSeen: byIsin[isin] ? byIsin[isin].firstSeen : now };
      if (!byIsin[isin]) added++;
      byIsin[isin] = item;
    });
    const cut = Date.now() - AI_EXPIRE_DAYS * 86400000;
    state.aiIdeas = { fetchedAt: now, model: res.model, profile: profNow, items: Object.keys(byIsin).map(function (k) { return byIsin[k]; })
      .filter(function (x) { return new Date(x.lastSeen).getTime() >= cut; }), lastAdded: added, lastRejected: rejected,
      usage: res.json.usage || null };
    logEvent("INFO", "KI-Vorschläge", res.model + ": " + added + " neu, " + rejected + " verworfen (ungültige/doppelte ISIN), aktiv " + state.aiIdeas.items.length);
    saveState(state);
    return true;
  } catch (e) {
    logEvent("FEHLER", "KI-Vorschläge", errText(e));
    state.aiIdeas = Object.assign({}, prev, { lastError: errText(e), lastErrorAt: new Date().toISOString() });
    saveState(state);
    return false;
  } finally {
    if (MAIN_WV) await setProgress(MAIN_WV, false, "", 0);
  }
}

/* Branche einer Kaufidee. Aktien: Sektor (deutsch, vereinheitlicht) und ggf. Industrie;
 * ETFs: Ausrichtung (breiter Markt, Region, Dividende, Anleihen). */
function buyIdeaBranche(state, c) {
  const e = state.buyIdeaPrices && state.buyIdeaPrices[c.isin];
  if (c.kind === "stock") {
    const sec = c.sector || (e && e.sector) || null;
    const ind = e && e.industry ? e.industry : null;
    return { label: sec ? canonLabel(sec, SECTOR_ALIASES) : "unbekannt", sub: ind, sector: sec ? canonLabel(sec, SECTOR_ALIASES) : null };
  }
  const n = String(c.name || "");
  let label = "ETF, branchenübergreifend";
  if (c.tier === "reserve") label = "Anleihen / Geldmarkt";
  else if (c.tier === "core") label = "Breiter Markt — alle Branchen";
  else if (c.gap === "em") label = "Schwellenländer — alle Branchen";
  else if (c.gap === "europe") label = "Europa — alle Branchen";
  else if (c.gap === "dividend" || /dividend|aristocrat/i.test(n)) label = "Dividendenwerte — branchenübergreifend";
  else {
    const hit = Object.keys(SECTOR_GROUPS).find(function (g) { return [g].concat(SECTOR_GROUPS[g]).some(function (a) { return a.length > 3 && labelKey(n).indexOf(labelKey(a)) >= 0; }); });
    if (hit) label = hit + " (Branchen-ETF)";
  }
  return { label: label, sub: null, sector: null };
}

/* Anteil einer Branche im Depot laut Durchschau (für die Einordnung beim Neukauf). */
let SECTOR_SHARE_CACHE = null;
function depotSectorShare(state, sector) {
  if (!sector) return null;
  if (!SECTOR_SHARE_CACHE || SECTOR_SHARE_CACHE.ver !== DATA_VER) {
    const map = {};
    try { computeOverview(state).sectorOverview.rows.forEach(function (r) { map[r.name] = r.pct; }); } catch (e) { /* ohne Durchschau */ }
    SECTOR_SHARE_CACHE = { ver: DATA_VER, map: map };
  }
  const v = SECTOR_SHARE_CACHE.map[sector];
  return validNumber(v) ? v : 0;
}

async function fetchAssetProfile(symbol) {
  const auth = await yahooAuth(false);
  if (!auth) throw new Error("kein Yahoo-Crumb");
  const data = await yahooAuthedJson("https://query2.finance.yahoo.com/v10/finance/quoteSummary/" + encodeURIComponent(symbol) +
    "?modules=assetProfile&formatted=false", auth);
  const r = data && data.quoteSummary && data.quoteSummary.result && data.quoteSummary.result[0];
  const ap = r && r.assetProfile;
  if (!ap || !ap.sector) throw new Error("kein Sektor");
  return { sector: ap.sector, industry: ap.industry || null };
}

function buyIdeasOn(state) { return !!(state && state.settings && state.settings.buyIdeas === true); }

function buyIdeaLink(c) {
  if (/^SYM:/.test(c.isin)) return "https://finance.yahoo.com/quote/" + encodeURIComponent(c.isin.slice(4));
  return c.kind === "etf"
    ? "https://www.justetf.com/de/etf-profile.html?isin=" + c.isin
    : "https://www.finanzen.net/suchergebnis.asp?frmAktiensucheTextfeld=" + c.isin;
}

function buyIdeasAnalysis(state, recRows) {
  const profile = allocationProfile(state);
  const held = {};
  state.positions.forEach(function (p) {
    held[String(p.wkn).toUpperCase()] = true;
    held[String(displayIsin(state, p.wkn)).toUpperCase()] = true;
  });
  const total = recTotalValue(recRows);
  const tierShare = { core: 0, satellite: 0, reserve: 0 };
  recRows.forEach(function (r) { if (r.share !== null) tierShare[r.tier || "satellite"] += r.share; });
  const rcB = recReserveCash(recRows);   // 🏦 Tagesgeld zählt als vorhandene Reserve
  if (rcB) tierShare.reserve += rcB.share;
  const has = { core: recRows.some(function (r) { return r.tier === "core"; }), reserve: !!rcB || recRows.some(function (r) { return r.tier === "reserve"; }) };
  const corePct = CORE_PCT[profile] || 80;
  const SP = strategyParams(state);
  const rti = retirementInfo(state), rf = rti ? rti.f : 0;
  const resPct = reservePct(state);
  const satTarget = (100 - (has.reserve ? resPct : 0)) * (100 - corePct) / 100 * (1 - 0.5 * rf);

  let ov = null;
  try { ov = computeOverview(state); } catch (e) { logEvent("WARNUNG", "Kaufideen", "Overview nicht berechenbar: " + errText(e)); }
  const sec = {}, cty = {};
  if (ov) {
    ov.sectorOverview.rows.forEach(function (r) { sec[r.name] = r.pct; });
    ov.countryOverview.rows.forEach(function (r) { cty[r.name] = r.pct; });
  }
  const secCov = ov ? ov.sectorOverview.coverage : 0, ctyCov = ov ? ov.countryOverview.coverage : 0;
  const sum = function (keys) { return keys.reduce(function (s, k) { return s + (cty[k] || 0); }, 0); };
  const emPct = sum(["China", "Taiwan", "Indien", "Brasilien", "Südkorea", "Schwellenländer"]);
  const euPct = sum(["Deutschland", "Großbritannien", "Frankreich", "Schweiz", "Niederlande", "Schweden", "Spanien", "Italien", "Dänemark", "Norwegen", "Finnland", "Belgien", "Österreich", "Europa"]);
  const lt = ov ? ov.summary.lookThrough : [];
  const hasSmall = recRows.some(function (r) { return /small ?cap|imi\b/i.test(String(r.etf.name || "")); });
  const depotYield = recRows.length && validNumber(recRows[0].etf.depotYieldPct) ? recRows[0].etf.depotYieldPct : null;

  const ideas = [];
  allBuyCandidates(state).forEach(function (c) {
    if (held[c.isin]) return;
    // Nur ausschüttende Wertpapiere: thesaurierende raus, ebenso geprüfte ohne Dividende in 12 M.
    if (buyIdeaAccumulating(c)) return;
    const cached = state.buyIdeaPrices && state.buyIdeaPrices[c.isin];
    if (cached && cached.divChecked && cached.symbol && !(cached.div && cached.div.perShare > 0)) return;
    const tip = cached && cached.trend && cached.trend.tip ? cached.trend : null;
    // Pool-Titel: nur mit Kursdaten, Dividende, günstigem Kurs oder Geheimtipp, indirekt < 3 %
    let poolAdv = null;
    if (c.pool) {
      if (!cached || !cached.divChecked || !(cached.div && cached.div.perShare > 0)) return;
      if ((c.poolPct || 0) >= POOL_MAX_INDIRECT) return;
      poolAdv = buyPriceAdvice(cached.trend);
      if (!tip && !(poolAdv && poolAdv.light === "🟢")) return;
    }
    let score = 0;
    const why = [];
    let startPct = null;
    if (c.tier === "core") {
      if (!has.core) { score = SP.buy.core; why.push("✓ Kern fehlt im Depot — Basis ist ein breiter, günstiger Indexfonds"); startPct = corePct; }
      else if (tierShare.core < corePct * 0.85) { score = 50; why.push("• Kernanteil " + fmtR1(tierShare.core) + " % unter Soll " + corePct + " % — bestehenden Kern-ETF aufstocken ist meist besser"); }
      else return;
    } else if (c.tier === "reserve") {
      if (has.reserve) {
        if (!rti || tierShare.reserve >= resPct * 0.85) return;
        score = 52 + Math.round(20 * rf);
        why.push("✓ Reserve " + fmtR1(tierShare.reserve) + " % unter Soll " + fmtR1(resPct) + " % (" + rti.label + ") — bestehende Reserve " + (rcB ? "(auch Tagesgeld) " : "") + "aufstocken geht auch");
        startPct = resPct - tierShare.reserve;
      } else {
        score = SP.buy.reserve + Math.round(15 * rf);
        why.push("✓ keine Reserve — rund 10 % kurzlaufend für Gelegenheiten" + (rti ? "; vor der Rente " + fmtR1(resPct) + " %" : ""));
        startPct = resPct;
      }
      if (c.isin === "IE00B14X4Q57") score -= 4;
    } else if (c.kind === "etf") {
      if (c.gap === "em") {
        if (ctyCov < 50 || emPct >= 8) return;
        score = clampScore(72 - emPct * 4, 45, 72) + SP.buy.em;
        why.push("✓ Schwellenländer nur " + fmtR1(emPct) + " % des Depots");
      } else if (c.gap === "europe") {
        if (ctyCov < 50 || euPct >= 12) return;
        score = clampScore(64 - euPct * 2, 45, 64) + SP.buy.europe;
        why.push("✓ Europa nur " + fmtR1(euPct) + " % des Depots");
      } else if (c.gap === "small") {
        if (hasSmall) return;
        score = SP.buy.small;
        why.push("• keine Nebenwerte im Depot");
      } else if (c.gap === "dividend") {
        if (depotYield !== null && depotYield >= (rti ? 3 : 2.2)) return;
        score = SP.buy.dividend + Math.round(18 * rf);
        if (rti) why.push("✓ " + rti.label + " — planbare Ausschüttungen");
        why.push("✓ Depot-Dividendenrendite " + (depotYield !== null ? fmtR2(depotYield) + " %" : "unbekannt") + " — Ausschüttungen stärken");
      } else if (c.ai) {
        score = SP.buy.ai + Math.round(8 * rf);
        why.push("✓ " + c.note);
        if (tierShare.satellite >= satTarget) { score -= 12; why.push("✗ Satelliten " + fmtR1(tierShare.satellite) + " % ≥ Soll " + fmtR1(satTarget) + " %"); }
      }
      if (rti && (c.gap === "em" || c.gap === "small")) { score -= Math.round(15 * rf); why.push("✗ höhere Schwankung — " + rti.label); }
      if (!c.gap && profile === "buffett" && /(tech|robot|clean|cyber|\bai\b|artificial|semiconductor|blockchain|innovation|disrupt)/i.test(String(c.name || ""))) { score -= 15; why.push("✗ Themen-/Trend-ETF — passt nicht zur Strategie Buffett"); }
      startPct = Math.min(THEME_CAP, Math.max(3, (satTarget - tierShare.satellite) / 2));   // wie bei Aktien: nach freiem Satellitenplatz
    } else {
      score = SP.buy.stock;
      why.push("✓ Qualität: " + c.note);
      // Bewertung: Strategien mit KGV-Grenze (Sicherheit, Buffett) meiden teure Aktien
      const cpe = (function () { const e0 = state.buyIdeaPrices && state.buyIdeaPrices[c.isin]; return e0 && validNumber(e0.pe) ? e0.pe : (validNumber(c.pe) ? c.pe : null); })();
      if (SP.buy.maxPe && validNumber(cpe) && cpe > 0) {
        if (cpe > SP.buy.maxPe) { score -= 12; why.push("✗ KGV " + fmtR1(cpe) + " über " + SP.buy.maxPe + " — zu teuer für die Strategie " + allocationProfileLabel(state)); }
        else if (cpe <= SP.buy.maxPe * 0.7) { score += 6; why.push("✓ KGV " + fmtR1(cpe) + " — fairer Preis"); }
      }
      const sp = sec[c.sector];
      if (secCov >= 50 && validNumber(sp)) {
        if (sp < 5) { score += 14; why.push("✓ Sektor " + c.sector + " nur " + fmtR1(sp) + " % des Depots"); }
        else if (sp > 25) { score -= 14; why.push("✗ Sektor " + c.sector + " schon " + fmtR1(sp) + " %"); }
      } else if (secCov >= 50 && !validNumber(sp)) { score += 14; why.push("✓ Sektor " + c.sector + " fehlt im Depot"); }
      const ind = lt.find(function (x) { return labelKey(x.name).indexOf(labelKey(c.key)) >= 0; });
      if (ind && ind.pct >= 0.5) {
        score -= ind.pct >= 3 ? 18 : (ind.pct >= 1 ? 9 : 3);
        why.push((ind.pct >= 1 ? "✗" : "•") + " über ETFs schon " + fmtR1(ind.pct) + " % indirekt gehalten");
      }
      if (tierShare.satellite >= satTarget) { score -= 18; why.push("✗ Satelliten " + fmtR1(tierShare.satellite) + " % ≥ Soll " + fmtR1(satTarget) + " %"); }
      else why.push("• Platz für Satelliten: " + fmtR1(Math.max(0, satTarget - tierShare.satellite)) + " %");
      if (rti) {
        if (c.key === "berkshire") { score -= Math.round(10 * rf); why.push("✗ keine Dividende — " + rti.label); }
        else { score += Math.round(8 * rf); why.push("✓ zahlt Dividende — " + rti.label); }
      }
      startPct = Math.min(stockCap(state), Math.max(2, (satTarget - tierShare.satellite) / 2 || 2));
    }
    if (c.pool) {
      score += 2;
      why.unshift("📦 " + c.note + (poolAdv ? " — Kurs " + poolAdv.light + " " + poolAdv.label : ""));
    }
    if (c.ai) {
      score += 4;
      why.unshift("🤖 KI-Vorschlag (" + new Date(c.aiDate).toLocaleDateString("de-DE") + "): " + (c.note || ""));
    }
    if (tip) {
      score += Math.round((6 + Math.min(8, Math.abs(Math.min(tip.dd, tip.vsSma)) / 3)) * SP.buy.tip);
      why.unshift("💎 Geheimtipp: 5 J ≈ " + fmtSigned(tip.cagr, 1) + " p. a., " + tip.up + " von " + tip.segs + " Jahren im Plus — aktuell " +
        fmtR1(Math.abs(tip.dd)) + " % unter 52W-Hoch, " + fmtSigned(tip.vsSma, 1) + " zur 200-Tage-Linie");
    }
    score = Math.round(clampScore(score, 0, 100));
    if (score < 45) return;
    if (tip && startPct) startPct = Math.min(startPct, 3);   // Geheimtipps nur als kleine Beimischung
    ideas.push({ c: c, score: score, why: why, tip: tip, startPct: startPct, startEur: total > 0 && startPct ? total * startPct / 100 : null });
  });
  ideas.sort(function (a, b) { return b.score - a.score; });
  // Kern und Reserve: nur die beste Idee zeigen (je ein ETF reicht). Geheimtipps getrennt, max. 4.
  const shown = {};
  const main = ideas.filter(function (x) {
    if (x.tip) return false;
    if (x.c.tier !== "core" && x.c.tier !== "reserve") return true;
    if (shown[x.c.tier]) return false;
    shown[x.c.tier] = true; return true;
  }).slice(0, 8);
  const tips = ideas.filter(function (x) { return x.tip; }).slice(0, 4);
  return main.concat(tips);
}

/* Tagesaktueller Kaufkurs je Kaufidee — einmal je Kalendertag, nur für die angezeigten
 * Ideen. Yahoo per ISIN (pickBestYahooQuote bevorzugt deutsche Handelsplätze in EUR), Fremdwährung
 * über den Tages-Wechselkurs; bei ETFs ohne Yahoo-Kurs notfalls Portalkurs (sofern in ⚙️ aktiv). */
/* Ausschüttungsrhythmus aus den Ex-Tagen der letzten 3 Jahre (Median-Abstand). */
function dividendRhythm(events) {
  const since = Date.now() - 3 * 365 * 86400000;
  const ts = (events || []).filter(function (e) { return e.t >= since; }).map(function (e) { return e.t; }).sort(function (a, b) { return a - b; });
  if (ts.length < 2) return ts.length === 1 ? { label: "jährlich", perYear: 1 } : null;
  const gaps = [];
  for (let i = 1; i < ts.length; i++) gaps.push((ts[i] - ts[i - 1]) / 86400000);
  gaps.sort(function (a, b) { return a - b; });
  const med = gaps[Math.floor(gaps.length / 2)];
  if (med <= 45) return { label: "monatlich", perYear: 12 };
  if (med <= 120) return { label: "vierteljährlich", perYear: 4 };
  if (med <= 240) return { label: "halbjährlich", perYear: 2 };
  return { label: "jährlich", perYear: 1 };
}

function buyIdeaAccumulating(c) { return c.kind === "etf" && /\(Acc\)|\b1C\b/i.test(c.name); }

function buyIdeaPriceFresh(entry) {
  return !!(entry && entry.fetchedAt && validNumber(entry.price) &&
    new Date(entry.fetchedAt).toDateString() === new Date().toDateString());
}

async function refreshBuyIdeaPrices(state, ideas, force) {
  if (!state.buyIdeaPrices) state.buyIdeaPrices = {};
  const todo = ideas.filter(function (x) {
    if (force) return true;   // „↻ neu einlesen“: alles sofort neu laden
    const e = state.buyIdeaPrices[x.c.isin];
    if (e && e.symbol && x.c.kind === "stock" && !x.c.sector && !("sector" in e)) return true;   // Branche fehlt noch
    // Pool-Titel nur wöchentlich auffrischen
    if (x.c.pool && e && e.fetchedAt && e.trend && "sma" in e.trend && e.divChecked &&
      Date.now() - new Date(e.fetchedAt).getTime() < POOL_REFRESH_DAYS * 86400000) return false;
    return !buyIdeaPriceFresh(e) || !e.divChecked || !("trend" in e) || (e.trend && !("sma" in e.trend));
  });
  if (!todo.length) return;
  const portalOn = !(state.settings && state.settings.portalPriceFallback === false);
  for (let i = 0; i < todo.length; i++) {
    const c = todo[i].c;
    const old = state.buyIdeaPrices[c.isin] || {};
    if (MAIN_WV) await setProgress(MAIN_WV, true, "Kaufkurs " + c.name + " …", Math.round(i / todo.length * 90));
    let entry = null, err = null;
    try {
      let sym = old.symbol || null;
      if (!sym && isinValid(c.isin)) { try { const r = await resolveInstrument(c.isin, c.isin); sym = r && r.symbol; } catch (e) { /* Ersatzsymbole versuchen */ } }
      // Ersatz-Kurssymbole, z. B. nach ISIN-Wechsel noch nicht bei Yahoo hinterlegt
      if (!sym && Array.isArray(c.syms)) {
        for (let k = 0; k < c.syms.length && !sym; k++) {
          try { const m0 = await fetchChartMeta(c.syms[k]); if (validNumber(m0.price) && m0.price > 0) sym = c.syms[k]; } catch (e) { /* nächstes Symbol */ }
        }
      }
      if (!sym) throw new Error("kein Kurssymbol gefunden");
      const m = await fetchChartMeta(sym);
      if (!validNumber(m.price) || m.price <= 0) throw new Error("kein Kurs");
      entry = { symbol: sym, price: m.price, currency: m.currency || "EUR", place: m.exchange || "", source: "Yahoo" };
    } catch (e) { err = errText(e); }
    if (!entry && c.kind === "etf" && portalOn) {
      try {
        const r = await fetchPortalPriceAny(c.isin);
        entry = { symbol: old.symbol || null, price: r.price, currency: r.currency, place: "", source: r.label };
      } catch (e) { err = (err ? err + " · " : "") + errText(e); }
    }
    // Branche: bei Aktien ohne hinterlegten Sektor einmalig nachladen
    if (entry && entry.symbol && c.kind === "stock" && !c.sector) {
      if (old.sector) { entry.sector = old.sector; entry.industry = old.industry || null; }
      else {
        try { const ap = await fetchAssetProfile(entry.symbol); entry.sector = ap.sector; entry.industry = ap.industry; }
        catch (e) { entry.sector = null; entry.industry = null; /* Branche bleibt unbekannt, nicht erneut versuchen */ }
      }
    }
    // Geheimtipp-Muster: 5 Jahre Wochenkurse über das Kurssymbol.
    if (entry && entry.symbol) {
      try {
        const hp = await fetchChartHistory(entry.symbol, "5J");
        entry.trend = tipMetrics(hp);
        const mk = tierMarketMetrics(hp);   // für die Stufe (Kern/Satellit/Reserve) aus Kennzahlen
        if (mk) { if (!entry.trend) entry.trend = {}; entry.trend.mkt = mk; }
      }
      catch (e) { entry.trend = old.trend || null; logEvent("WARNUNG", "Kaufideen", c.name + ": Kurshistorie nicht ladbar — " + errText(e)); }
    }
    // Dividenden: Ex-Tage und Beträge über das Kurssymbol; thesaurierende ETFs ohne Abruf.
    if (entry && entry.symbol && !buyIdeaAccumulating(c)) {
      try {
        const ev = await fetchDividendEvents(entry.symbol);
        const yearAgo = Date.now() - 365 * 86400000;
        const last12 = ev.filter(function (e) { return e.t >= yearAgo; });
        entry.div = {
          perShare: last12.reduce(function (a, e) { return a + e.amount; }, 0),
          count12: last12.length, currency: ev.currency || entry.currency,
          rhythm: dividendRhythm(ev), lastT: ev.length ? ev[ev.length - 1].t : null,
          lastAmount: ev.length ? ev[ev.length - 1].amount : null,
        };
      } catch (e) { logEvent("WARNUNG", "Kaufideen", c.name + ": Dividenden nicht ladbar — " + errText(e)); entry.div = old.div || null; }
    }
    if (entry) state.buyIdeaPrices[c.isin] = Object.assign(entry, { fetchedAt: new Date().toISOString(), error: null, divChecked: true });
    else {
      state.buyIdeaPrices[c.isin] = Object.assign({}, old, { error: err || "kein Kurs" });
      logEvent("WARNUNG", "Kaufideen", c.name + " (" + c.isin + "): Kaufkurs nicht ladbar — " + (err || "kein Kurs"));
    }
  }
  const curs = [];
  Object.keys(state.buyIdeaPrices).forEach(function (k) {
    const e = state.buyIdeaPrices[k];
    if (e.currency) curs.push(e.currency);
    if (e.div && e.div.currency) curs.push(e.div.currency);
  });
  if (MAIN_WV) await setProgress(MAIN_WV, true, "Wechselkurse …", 95);
  try { await refreshFxRates(state, curs); } catch (e) { logEvent("WARNUNG", "Kaufideen", "Wechselkurse: " + errText(e)); }
  if (MAIN_WV) await setProgress(MAIN_WV, false, "", 0);
  saveState(state);
}

function buyIdeaPriceHtml(state, x) {
  const e = state.buyIdeaPrices && state.buyIdeaPrices[x.c.isin];
  if (!e || !validNumber(e.price)) return { price: "nicht verfügbar", qty: "–", eur: null, div: buyIdeaAccumulating(x.c) ? "thesaurierend" : "–", divDetail: "", rhythm: buyIdeaAccumulating(x.c) ? "keine Ausschüttung" : "–" };
  const eur = toEurNow(e.price, e.currency, state);
  const fresh = buyIdeaPriceFresh(e);
  const when = new Date(e.fetchedAt);
  const stamp = fresh ? "heute " + when.toLocaleTimeString("de-DE", { hour: "2-digit", minute: "2-digit" }) : "Stand " + when.toLocaleDateString("de-DE");
  const detail = (String(e.currency).toUpperCase() !== "EUR" ? e.currency + " " + fmtR2(e.price) + " · " : "") +
    (e.place ? e.place + " · " : (e.source !== "Yahoo" ? e.source + " · " : "")) + stamp;
  const qty = validNumber(eur) && eur > 0 && x.startEur ? "≈ " + fmtQty(Math.floor(x.startEur / eur * 100) / 100) + " Stk." : "–";
  // Dividende
  let div = "–", divDetail = "", rhythm = "–";
  if (buyIdeaAccumulating(x.c)) { div = "thesaurierend"; rhythm = "keine Ausschüttung"; }
  else if (e.div) {
    const d = e.div;
    const perEur = d.perShare > 0 ? toEurNow(d.perShare, d.currency, state) : 0;
    if (!(d.perShare > 0)) { div = "keine"; rhythm = d.rhythm ? "zuletzt " + d.rhythm.label : "keine Ausschüttung"; }
    else {
      div = validNumber(perEur) ? fmtEur(perEur) + " je Stk." : fmtR2(d.perShare) + " " + d.currency + " je Stk.";
      const yld = validNumber(perEur) && validNumber(eur) && eur > 0 ? perEur / eur * 100 : null;
      const startDiv = validNumber(perEur) && validNumber(eur) && eur > 0 && x.startEur ? x.startEur / eur * perEur : null;
      divDetail = (yld !== null ? fmtR2(yld) + " % Rendite" : "") + (startDiv !== null ? " · ≈ " + fmtEur(startDiv) + "/J. für Startgröße" : "");
      rhythm = d.rhythm ? d.rhythm.label + " (" + d.count12 + "× in 12 M)" : d.count12 + "× in 12 M";
      if (d.lastT) rhythm += " · zuletzt " + new Date(d.lastT).toLocaleDateString("de-DE") + (validNumber(d.lastAmount) ? " " + fmtR2(d.lastAmount) + " " + d.currency : "");
    }
  }
  return { price: validNumber(eur) ? fmtEur(eur) : "Wechselkurs fehlt", detail: detail, qty: qty, eur: eur, div: div, divDetail: divDetail, rhythm: rhythm };
}

function buyIdeasHtml(state, recRows, plan) {
  let list;
  try { list = buyIdeasAnalysis(state, recRows); }
  catch (e) {
    logEvent("FEHLER", "Kaufideen", "Berechnung fehlgeschlagen: " + errText(e));
    return "<p class='hint'>Kaufideen nicht berechenbar (Details im Fehlerlog).</p>";
  }
  if (!list.length) return (!aiOn(state) && !poolOn(state))
    ? "<p class='hint'>Keine Recherchequelle aktiv — unter ⚙️ → Sollgewichtung „🤖 KI-Vorschläge“ und/oder „📦 Kandidaten aus ETF-Beständen“ einschalten.</p>"
    : (aiOn(state) && !aiKey() ? "<p class='hint'>🤖 KI-Vorschläge brauchen einen API-Schlüssel (⚙️). Bis dahin nur Kandidaten aus deinen ETFs.</p>" : "") +
      "<p class='hint'>Aktuell keine Lücke, die ein neues ausschüttendes Wertpapier sinnvoller füllt als das Aufstocken bestehender Positionen.</p>";
  const main = list.filter(function (x) { return !x.tip; }), tips = list.filter(function (x) { return x.tip; });
  if (plan) {   // gleiche Reihenfolge wie im Sparplan
    const pk = function (x) { const i = plan.index["i:" + x.c.isin]; return i && i.rank ? i.rank : 999; };
    main.sort(function (a, b) { return pk(a) - pk(b) || b.score - a.score; });
  }
  return (main.length ? cardsOf(main) : "<p class='hint'>Keine regulären Kaufideen.</p>") +
    "<h3 class='miniHead'>💎 Geheimtipps (" + tips.length + ")</h3>" +
    "<div class='pageWarn'>⚠️ Antizyklisch: Diese Titel sind über 5 Jahre stetig gestiegen, notieren aber gerade unter Trend bzw. 52W-Hoch. Ein Rücksetzer kann weitergehen oder eine Trendwende sein — die Vergangenheit ist keine Garantie. Nur als kleine Beimischung (max. 3 %).</div>" +
    (tips.length ? cardsOf(tips) : "<p class='hint'>Heute zeigt kein recherchierter Titel das Geheimtipp-Muster.</p>");
  function cardsOf(arr) { return arr.map(function (x, i) {
    const c = x.c;
    const label = (x.tip ? "💎 Geheimtipp · " : "") + (c.ai ? "🤖 KI-Vorschlag · " : "") + (c.pool ? "📦 aus deinen ETFs · " : "") + (x.score >= 70 ? "🟢 Hohe Priorität" : (x.score >= 58 ? "🟢 Kaufkandidat" : "🟡 Beimischung prüfen"));
    const start = x.startPct ? "≈ " + fmtR1(x.startPct) + " %" + (x.startEur ? " (" + fmtEur(x.startEur) + ")" : "") : "–";
    const px = buyIdeaPriceHtml(state, x);
    return '<div class="rec' + (x.tip ? ' tipCard' : '') + (c.ai ? ' aiCard' : '') + '">' +
      '<div class="recTop"><div><span class="recRank">' + (x.tip ? '💎' : '#' + (i + 1)) + '</span><b>' + esc(c.name) + '</b>' +
      '<div class="recKind">' + isinChip(c.isin) + '</div><div class="recKind">' + (c.kind === "etf" ? "ETF" : "Einzelaktie") + ' · ' +
      esc(TIER_LABELS[c.tier || "satellite"]) + ' · 🏭 ' + esc(buyIdeaBranche(state, c).label) + '</div></div>' +
      '<div class="recScore">' + x.score + '<small>/100</small></div></div>' +
      '<div class="recLabel">' + label + '</div>' +
      (x.tip ? '<div class="planBadge">⏸ Nicht im Sparplan: Geheimtipp — nur als Einzelkauf (max. 3 %)</div>' : planBadge(plan, "i:" + c.isin)) +
      '<div class="recGrid"><div><span>Kaufkurs (€)</span><b>' + esc(px.price) + '</b>' + (px.detail ? '<span>' + esc(px.detail) + '</span>' : '') + '</div>' +
      '<div><span>Startgröße (Sollanteil)</span><b>' + esc(start) + '</b></div>' +
      '<div><span>Stückzahl dafür</span><b>' + esc(px.qty) + '</b></div>' +
      (function () {
        const br = buyIdeaBranche(state, c);
        const sh = br.sector ? depotSectorShare(state, br.sector) : null;
        return '<div><span>Branche</span><b>🏭 ' + esc(br.label) + '</b>' +
          (br.sub || sh !== null ? '<span>' + esc((br.sub ? br.sub : "") + (br.sub && sh !== null ? " · " : "") + (sh !== null ? "im Depot bisher " + fmtR1(sh) + " %" : "")) + '</span>' : '') + '</div>';
      })() +
      (function () {
        const e2 = state.buyIdeaPrices && state.buyIdeaPrices[c.isin];
        const a = buyPriceAdvice(e2 && e2.trend);
        if (!a) return '<div><span>Kaufkurs-Einschätzung</span><b>keine Kurshistorie</b></div>';
        const cur = e2.currency || "EUR";
        const lim = toEurNow(a.limit, cur, state), mx = toEurNow(a.max, cur, state);
        return '<div><span>Kaufkurs-Einschätzung</span><b>' + a.light + ' ' + esc(a.label) + '</b><span>' + esc(a.note) + '</span></div>' +
          '<div><span>Empfohlener Kaufkurs (Limit)</span><b>' + (validNumber(lim) ? esc(fmtEur(lim)) : '–') + '</b>' +
          '<span>' + (validNumber(mx) ? 'bis zu ' + esc(fmtEur(mx)) + ' vertretbar' : '') + '</span></div>';
      })() +
      '<div><span>Dividende 12 M</span><b>' + esc(px.div) + '</b>' + (px.divDetail ? '<span>' + esc(px.divDetail) + '</span>' : '') + '</div>' +
      '<div><span>Ausschüttung</span><b>' + esc(px.rhythm) + '</b></div>' +
      '<div><span>Info</span><b><a href="scriptable:news-open?u=' + encodeURIComponent(buyIdeaLink(c)) + '" style="color:var(--accent);text-decoration:none">' + (c.kind === "etf" ? "justETF ↗" : "finanzen.net ↗") + '</a></b></div></div>' +
      '<div class="recWhy">' + x.why.map(esc).join("<br>") + '<br>• ' + esc(c.note) + '</div>' +
      '</div>';
  }).join(""); }
}

/* Zusammenfassung: je Bereich höchstens 3 Titel, ein Satz Begründung. */
function plainWhy(t) { return String(t || "").replace(/^[✓✗•💎⚠️\s]+/u, "").trim(); }

/* ISIN-Kopier-Chip: antippen → Zwischenablage (Pasteboard) + kurze Bestätigung. */
function isinChip(isin) {
  const v = String(isin || "").trim();
  if (!v) return "";
  const isSym = /^SYM:/.test(v);
  const val = isSym ? v.slice(4) : v;
  return '<a class="isinChip" href="scriptable:copy?t=' + encodeURIComponent(val) + '">📋 ' + (isSym ? "Symbol " : "ISIN ") + esc(val) + '</a>';
}

function summaryHtml(state, recRows, sellRows, ideas, plan) {
  const total = recRows.reduce(function (s, r) { return s + (r.value || 0); }, 0);
  function group(h) { return /class=.sumItem/.test(h) ? '<div class="iosGroup">' + h + '</div>' : h; }
  function item(icon, name, amount, why, isin) {
    return '<div class="sumItem"><div class="sumHead"><span>' + icon + ' <b>' + esc(name) + '</b></span>' +
      (amount ? '<span class="sumAmt">' + esc(amount) + '</span>' : '') + '</div>' +
      (isin ? '<div class="sumWhy">' + isinChip(isin) + '</div>' : '') +
      '<div class="sumWhy">' + esc(why) + '</div></div>';
  }
  // Aufstocken: Score ≥ 60, sortiert nach Score
  // Aufstocken: aus dem Sparplan (gleiche Reihenfolge/Ausschlüsse); ohne Plan Score ≥ 60 unter Soll.
  const planHeld = plan ? plan.plans.filter(function (it) { return it.kind === "held"; }) : null;
  const planNew = plan ? plan.plans.filter(function (it) { return it.kind === "new"; }) : null;
  const rate = function (it) { return plan.virtual ? fmtR1(it.pct) + " %" : fmtEur(it.rate) + "/M."; };
  const top = planHeld
    ? planHeld.slice(0, 3).map(function (it) { return it.row; })
    : recRows.filter(function (r) { return r.score !== null && r.score >= 60 && (r.share === null || r.share < r.targetShare); }).slice(0, 3);
  const topHtml = top.map(function (r) {
    const gap = total > 0 && r.value !== null ? r.targetShare / 100 * total - r.value : null;
    const bits = ["Score " + r.score + "/100"];
    if (r.share !== null) bits.push(r.share < r.targetShare * 0.85 ? "unter Soll (" + fmtR1(r.share) + " % statt " + fmtR1(r.targetShare) + " %)" : "Gewicht " + fmtR1(r.share) + " % / Soll " + fmtR1(r.targetShare) + " %");
    if (r.dividend && r.dividend.yieldPct !== null) bits.push("Dividende " + fmtR2(r.dividend.yieldPct) + " %");
    if (r.expected && r.expected.value !== null) bits.push("Erwartung " + fmtSigned(r.expected.value, 1) + " p. a.");
    const pit = plan ? plan.index["w:" + r.etf.wkn] : null;
    if (pit && total > 0 && (pit.item.overlapValue || pit.item.indirect)) {
      // gleiche Basis wie im Sparplan: inkl. überschneidender ETFs / indirekter Anteile
      const eff = (pit.item.value + (pit.item.indirect || 0) + (pit.item.overlapValue || 0)) / total * 100;
      bits[1] = "Gewicht inkl. " + (pit.item.overlapValue ? "überschneidendem ETF" : "ETF-Anteilen") + " " + fmtR1(eff) + " % / Soll " + fmtR1(pit.item.target) + " %";
      if (eff > pit.item.target && pit.rate > 0) bits.push("leicht über Soll — wird als Basis stetig weiter bespart");
    } else if (pit && pit.rate > 0 && r.share !== null && r.share > r.targetShare) bits.push("leicht über Soll — wird als Basis stetig weiter bespart");
    const amount = pit && pit.rate > 0 ? "💰 " + rate(pit.item) : (gap !== null && gap > 0 ? "≈ " + fmtEur(gap) : "");
    if (pit && pit.need > 0) bits.push("Lücke bis Soll ≈ " + fmtEur(pit.need));
    return item("🎯", r.etf.name, amount, bits.join(" · ") + " (" + r.tierLabel + ").", displayIsin(state, r.etf.wkn));
  }).join("");
  // Verkaufen: ab 3 Punkten
  const sells = (sellRows || []).filter(function (x) { return x.row.score !== null && x.pts >= 3; }).slice(0, 3);
  const sellHtml2 = sells.map(function (x) {
    const contra = x.why.filter(function (w) { return w.i === "✗"; }).slice(0, 2).map(function (w) { return plainWhy(w.t); });
    const amt = x.reduce ? "≈ " + fmtEur(x.reduce.eur) + " (" + fmtQty(x.reduce.qty) + " Stk.)" : "";
    return item(x.light, x.etf.name, amt, x.label + ": " + (contra.join("; ") || "mehrere schwache Signale") + ".");
  }).join("");
  // Kaufen (neu)
  let buyHtml;
  if (!buyIdeasOn(state)) buyHtml = "<p class='hint'>Neue Kaufideen sind aus — einschalten unter ⚙️ → Sollgewichtung → „💡 Neue Kaufideen“.</p>";
  else {
    const reg = planNew
      ? planNew.slice(0, 3).map(function (it) { return it.idea; })
      : (ideas || []).filter(function (x) { return !x.tip; }).slice(0, 3);
    const tip = (ideas || []).filter(function (x) { return x.tip; })[0];
    buyHtml = reg.concat(tip ? [tip] : []).map(function (x) {
      const px = buyIdeaPriceHtml(state, x);
      const pit = plan && !x.tip ? plan.index["i:" + x.c.isin] : null;
      const amt = pit && pit.rate > 0 ? "💰 " + rate(pit.item) + (x.startEur ? " · Ziel ≈ " + fmtEur(x.startEur) : "")
        : (x.startEur ? "≈ " + fmtEur(x.startEur) + (px.qty !== "–" ? " · " + px.qty : "") : "");
      const e2 = state.buyIdeaPrices && state.buyIdeaPrices[x.c.isin];
      const adv = buyPriceAdvice(e2 && e2.trend);
      const limEur = adv ? toEurNow(adv.limit, e2.currency || "EUR", state) : null;
      const br0 = buyIdeaBranche(state, x.c);
      const why = "🏭 " + br0.label + " · " + plainWhy(x.why[0]) + (px.div && px.div !== "–" ? " · Dividende " + px.div + (px.rhythm && px.rhythm !== "–" ? ", " + px.rhythm.split(" (")[0] : "") : "") +
        (adv ? " · " + adv.light + " " + adv.label + (validNumber(limEur) ? ", Limit ≈ " + fmtEur(limEur) : "") : "") + ".";
      return item(x.tip ? "💎" : "💡", x.c.name + (x.tip ? " (Geheimtipp)" : ""), amt, why, x.c.isin);
    }).join("") || "<p class='hint'>Keine neue Kaufidee — Aufstocken bestehender Positionen reicht.</p>";
  }
  // Fazit
  const steps = [];
  const urgent = sells.filter(function (x) { return x.pts >= 5; })[0];
  if (urgent) steps.push("Zuerst " + urgent.etf.name + " prüfen — " + urgent.label + ".");
  if (plan && plan.plans.length && !plan.virtual) {
    steps.push("Sparplan " + fmtEur(plan.saving) + "/Monat: " + plan.plans.slice(0, 3).map(function (it) { return it.name + " " + fmtEur(it.rate); }).join(", ") + (plan.plans.length > 3 ? " und weitere." : "."));
  } else if (top[0]) steps.push(top[0].etf.name + " aufstocken" + (total > 0 && top[0].value !== null && top[0].targetShare / 100 * total > top[0].value ? " (≈ " + fmtEur(top[0].targetShare / 100 * total - top[0].value) + " bis Soll)" : "") + ".");
  const firstIdea = plan && !plan.virtual ? null : (planNew && planNew[0] ? planNew[0].idea : (ideas || []).filter(function (x) { return !x.tip; })[0]);
  if (buyIdeasOn(state) && firstIdea) steps.push("Neu beimischen: " + firstIdea.c.name + (firstIdea.startEur ? " (≈ " + fmtEur(firstIdea.startEur) + ")" : "") + ".");
  if (!steps.length) steps.push("Depot liegt im Rahmen — halten und regelmäßig nach Sollgewicht nachkaufen.");
  const ri = retirementInfo(state);
  return '<div class="sumBox"><b>Empfehlung</b><p>' + esc(steps.join(" ")) + '</p>' +
    (ri ? '<small>🏖️ ' + esc(ri.label) + ' — Reserve ' + fmtR1(reservePct(state)) + ' %, Dividende und Stabilität höher gewichtet.</small>' : '') + '</div>' +
    '<h3 class="miniHead">💡 Kaufen (neu)</h3>' + (buyIdeasOn(state) ? ideasRefreshBar(state) : '') + group(buyHtml) +
    '<h3 class="miniHead">🎯 Aufstocken</h3>' + (topHtml ? group(topHtml) : "<p class='hint'>Keine Position mit Score ab 60 unter Sollgewicht.</p>") +
    '<h3 class="miniHead">📉 Verkaufen / Reduzieren</h3>' + (sellHtml2 ? group(sellHtml2) : "<p class='hint'>Kein deutlicher Verkaufsdruck — alles halten.</p>") +
    "<p class='foot'>Kurzfassung der Tabs Aufstocken, Kaufen und Verkaufen. Orientierung auf Basis einfacher Regeln, keine Anlageberatung.</p>";
}

/* ---------------------------------------------------------------------------
 * Hochrechnung bis Rentenbeginn. Je Position monatlich verzinst:
 * Rendite p. a. = Kurserwartung (historisch, auf −5…+12 % begrenzt; ohne Daten
 * Kern 5 %, Satellit 6 %, Reserve 2,5 %) + Dividendenrendite (wiederangelegt).
 * Szenarien: pessimistisch −3 Pkt., Basis, optimistisch +2 Pkt. (Reserve ±0,5).
 * Sparrate (⚙️) wird nach Sollgewicht verteilt. Steuern/Kosten nicht berücksichtigt.
 * -------------------------------------------------------------------------*/
const PROJ_INFLATION = 2;

function retirementProjection(state, recRows) {
  const ri = retirementInfo(state);
  if (!ri) return null;
  const months = Math.max(0, Math.round(ri.years * 12));
  const setSaving = Math.max(0, Number(retirementSettings(state).saving) || 0);
  const cmAll = committedPlans(state);
  const cmTotal = committedTotal(state);
  // Umgesetzte Sparpläne: feste Raten je Titel; Rest der Sparrate nach Sollgewicht
  const saving = Math.max(setSaving, cmTotal);
  const rest = Math.max(0, setSaving - cmTotal);
  const pos = recRows.filter(function (r) { return validNumber(r.value) && r.value > 0; }).map(function (r) {
    const fallback = r.tier === "reserve" ? 2.5 : (r.tier === "core" ? 5 : 6);
    const ex = r.expected && validNumber(r.expected.value) ? clampScore(r.expected.value, -5, 12) : fallback;
    const dy = r.dividend && validNumber(r.dividend.yieldPct) ? clampScore(r.dividend.yieldPct, 0, 10) : 0;
    const cm = commitOf(state, displayIsin(state, r.etf.wkn));
    return { r: r, value: r.value, rate: (r.tier === "reserve" ? Math.min(ex, 3.5) : ex) + dy, dy: dy, w: r.targetShare || 0, fixed: cm ? cm.rate : 0 };
  });
  // umgesetzte neue Titel, die noch nicht im Depot sind: starten bei 0 €
  Object.keys(cmAll).forEach(function (isin) {
    if (pos.some(function (p) { return String(displayIsin(state, p.r.etf.wkn)).toUpperCase() === isin; })) return;
    const cm = cmAll[isin];
    const bp = state.buyIdeaPrices && state.buyIdeaPrices[isin];
    let dy = 0;
    if (bp && bp.div && bp.div.perShare > 0 && validNumber(bp.price) && bp.price > 0) dy = clampScore(toEurNow(bp.div.perShare, bp.div.currency, state) / toEurNow(bp.price, bp.currency, state) * 100, 0, 10) || 0;
    const ex = bp && bp.trend && validNumber(bp.trend.cagr) ? clampScore(bp.trend.cagr, -5, 12) : (cm.kind === "etf" ? 5 : 6);
    pos.push({ r: { tier: "satellite", etf: { name: cm.name + " (Sparplan neu)", wkn: isin } }, value: 0, rate: ex + dy, dy: dy, w: 0, fixed: cm.rate });
  });
  if (!pos.length) return null;
  // Monatliche Einzahlung je Position: umgesetzte Sparpläne = feste Rate; Rest der Sparrate nur auf Positionen
  // OHNE festen Plan (nach Sollgewicht). Gibt es keine solchen, geht der Rest nach Sollgewicht an alle.
  const wSumAll = pos.reduce(function (s, p) { return s + p.w; }, 0);
  const wSumRest = pos.reduce(function (s, p) { return s + (p.fixed ? 0 : p.w); }, 0);
  const monthlyIn = pos.map(function (p) {
    if (cmTotal > 0) {
      if (wSumRest > 0) return p.fixed ? p.fixed : rest * p.w / wSumRest;
      return p.fixed + (wSumAll > 0 ? rest * p.w / wSumAll : rest / pos.length);
    }
    return wSumAll > 0 ? saving * p.w / wSumAll : saving / pos.length;
  });
  const now = pos.reduce(function (s, p) { return s + p.value; }, 0);
  const scen = { pess: -3, base: 0, opt: 2 };
  const out = { now: now, months: months, saving: saving, committed: cmTotal, info: ri, scen: {}, years: [], posBase: [] };
  Object.keys(scen).forEach(function (k) {
    const vals = pos.map(function (p) { return p.value; });
    const yearly = [];
    let divSum = 0;
    for (let m = 1; m <= months; m++) {
      // Dividende dieses Monats (vor Wiederanlage) — Grundlage für den Ø pro Monat.
      pos.forEach(function (p, i) { divSum += vals[i] * p.dy / 100 / 12; });
      pos.forEach(function (p, i) {
        const adj = p.r.tier === "reserve" ? Math.sign(scen[k]) * 0.5 : scen[k];
        const rm = Math.pow(1 + (p.rate + adj) / 100, 1 / 12) - 1;
        vals[i] = vals[i] * (1 + rm) + monthlyIn[i];
      });
      if (m % 12 === 0 || m === months) yearly.push({ m: m, v: vals.reduce(function (a, b) { return a + b; }, 0),
        divMonth: pos.reduce(function (s2, p, i) { return s2 + vals[i] * p.dy / 100; }, 0) / 12 });
    }
    const end = vals.reduce(function (a, b) { return a + b; }, 0);
    const divMonthEnd = pos.reduce(function (s2, p, i) { return s2 + vals[i] * p.dy / 100; }, 0) / 12;
    out.scen[k] = { end: end, real: end / Math.pow(1 + PROJ_INFLATION / 100, months / 12), yearly: yearly,
      divMonthEnd: divMonthEnd, divMonthAvg: months ? divSum / months : divMonthEnd, divTotal: divSum };
    if (k === "base") out.posBase = pos.map(function (p, i) { return { name: p.r.etf.name, now: p.value, end: vals[i], rate: p.rate, divEnd: vals[i] * p.dy / 100 }; });
  });
  out.paid = now + saving * months;
  out.divMonthNow = pos.reduce(function (s2, p) { return s2 + p.value * p.dy / 100; }, 0) / 12;
  out.divEnd = out.posBase.reduce(function (s, p) { return s + p.divEnd; }, 0);
  out.rateAvg = now > 0 ? pos.reduce(function (s, p) { return s + p.rate * p.value; }, 0) / now : null;
  return out;
}

function projectionHtml(state, recRows, compact) {
  if (!retirementInfo(state)) return "<p class='hint'>Ruhestandsplanung ist aus — einschalten unter ⚙️ → Sollgewichtung → „🏖️ Ruhestandsplanung“.</p>";
  let pr;
  try { pr = retirementProjection(state, recRows); }
  catch (e) { logEvent("FEHLER", "Hochrechnung", errText(e)); return "<p class='hint'>Hochrechnung nicht berechenbar (Details im Fehlerlog).</p>"; }
  if (!pr) return "<p class='hint'>Keine bewerteten Positionen für die Hochrechnung.</p>";
  const b = pr.scen.base, lo = pr.scen.pess, hi = pr.scen.opt;
  const head = '<div class="sumBox"><b>Depotwert zum ' + esc(pr.info.label.replace(/^Rentenbeginn /, "Rentenbeginn ")) + '</b>' +
    '<p style="font-size:28px;font-weight:700;margin:6px 0 2px">≈ ' + fmtEur(b.end) + '</p>' +
    '<small>Spanne ' + fmtEur(lo.end) + ' – ' + fmtEur(hi.end) + ' · heute ' + fmtEur(pr.now) +
    (pr.saving ? ' · Sparrate ' + fmtEur(pr.saving) + '/Monat' + (pr.committed ? ' (davon ✅ umgesetzt ' + fmtEur(pr.committed) + ')' : '') : '') + '</small>' +
    '<p style="margin:12px 0 2px;font-size:13px;color:var(--dim)">Dividende im Ø pro Monat</p>' +
    '<p style="font-size:22px;font-weight:700;margin:0">≈ ' + fmtEur(b.divMonthEnd) + ' <span style="font-size:13px;font-weight:400;color:var(--dim)">zum Rentenbeginn</span></p>' +
    '<small>heute ≈ ' + fmtEur(pr.divMonthNow) + ' · Ø bis zur Rente ≈ ' + fmtEur(b.divMonthAvg) + ' · Spanne zum Rentenbeginn ' + fmtEur(lo.divMonthEnd) + ' – ' + fmtEur(hi.divMonthEnd) + '</small></div>';
  if (compact) return head;
  const tile = function (l, v, sub) { return '<div class="stat"><span style="display:block;font-size:12px;color:var(--dim)">' + l + '</span><b style="font-size:17px">' + v + '</b>' + (sub ? '<div style="font-size:12px;color:var(--dim)">' + sub + '</div>' : '') + '</div>'; };
  const stats = '<div class="stats" style="margin-top:10px">' +
    tile("Pessimistisch", fmtEur(lo.end), "Kaufkraft " + fmtEur(lo.real)) +
    tile("Basis", fmtEur(b.end), "Kaufkraft " + fmtEur(b.real)) +
    tile("Optimistisch", fmtEur(hi.end), "Kaufkraft " + fmtEur(hi.real)) +
    tile("Dividende/Monat zum Rentenbeginn", "≈ " + fmtEur(b.divMonthEnd), "≈ " + fmtEur(b.divMonthEnd * 12) + " im Jahr (Basis)") +
    tile("Ø Dividende/Monat bis zur Rente", "≈ " + fmtEur(b.divMonthAvg), "gesamt ≈ " + fmtEur(b.divTotal) + " (wiederangelegt)") +
    tile("Eingezahlt bis dahin", fmtEur(pr.paid), "Zuwachs Basis " + fmtEur(b.end - pr.paid)) +
    tile("Ø Rendite p. a.", validNumber(pr.rateAvg) ? fmtSigned(pr.rateAvg, 1) : "–", "Kurs + Dividende, wertgewichtet") + '</div>';
  const rows = b.yearly.map(function (y, i) {
    const d = new Date(); d.setMonth(d.getMonth() + y.m);
    const mmYY = String(d.getMonth() + 1).padStart(2, "0") + "/" + d.getFullYear();
    return '<div class="sumItem"><div class="sumHead"><span><b>' + (y.m === pr.months ? "Rentenbeginn " + mmYY : mmYY + " (in " + Math.round(y.m / 12) + " J.)") + '</b></span><span class="sumAmt">' + fmtEur(y.v) + '</span></div>' +
      '<div class="sumWhy">' + fmtEur(lo.yearly[i].v) + ' – ' + fmtEur(hi.yearly[i].v) + ' · Dividende ≈ ' + fmtEur(y.divMonth) + '/Monat</div></div>';
  }).join("");
  const posRows = pr.posBase.slice().sort(function (a, b2) { return b2.end - a.end; }).map(function (p) {
    return '<div class="sumItem"><div class="sumHead"><span><b>' + esc(p.name) + '</b></span><span class="sumAmt">' + fmtEur(p.end) + '</span></div>' +
      '<div class="sumWhy">heute ' + fmtEur(p.now) + ' · ' + fmtSigned(p.rate, 1) + ' p. a. · Dividende ≈ ' + fmtEur(p.divEnd / 12) + '/Monat (' + fmtEur(p.divEnd) + '/Jahr)</div></div>';
  }).join("");
  return head + stats +
    '<h3 class="miniHead">Verlauf (Basis, Spanne darunter)</h3><div class="iosGroup">' + rows + '</div>' +
    '<h3 class="miniHead">Je Position (Basis)</h3><div class="iosGroup">' + posRows + '</div>' +
    "<p class='foot'>Rendite je Position = historische Kurserwartung (begrenzt auf −5…+12 % p. a.; ohne Daten Kern 5 %, Satellit 6 %, Reserve 2,5 %) plus Dividendenrendite, Dividenden wiederangelegt, monatlich verzinst. Pessimistisch −3, optimistisch +2 Prozentpunkte (Reserve ±0,5). Sparrate nach Sollgewicht verteilt. Kaufkraft bei " + PROJ_INFLATION + " % Inflation. Steuern, Kosten und Umschichtungen nicht berücksichtigt — Modellrechnung, keine Prognose oder Garantie.</p>";
}

/* ---------------------------------------------------------------------------
 * Sparplan-Vorschlag. Ziel: in 12 Monaten (bzw. bis Rentenbeginn, falls
 * früher) möglichst nah ans Sollgewicht. Universum = bestehende Positionen (ohne
 * Verkaufskandidaten ab 3 Punkten und ohne Mitarbeiteraktien mit Sperrfrist) + empfohlene
 * neue Kaufideen (ohne Geheimtipps; Sollanteil = Startgröße). Bedarf je Titel =
 * Soll × künftiger Depotwert − heutiger Wert; Sparrate anteilig zum Bedarf, auf 5 €
 * gerundet, Mindestrate 25 € (kleinere entfallen, Rest wird umverteilt), max. 8 Sparpläne.
 * -------------------------------------------------------------------------*/
const SAVINGS_MIN_RATE = 25, SAVINGS_STEP = 5, SAVINGS_MAX_PLANS = 8, SAVINGS_OVERLAP_MAX = 60;
const SAVINGS_HYST_EUR = 25, SAVINGS_HYST_PCT = 20;   // Vorschlag ändert eine laufende Rate erst ab dieser Abweichung

/* Umgesetzte Sparpläne: state.savingsCommit[ISIN] = { name, rate, since, wkn } */
function committedPlans(state) { return (state && state.savingsCommit) || {}; }
function commitOf(state, isin) { const c = committedPlans(state)[String(isin || "").toUpperCase()]; return c && validNumber(c.rate) ? c : null; }
function committedTotal(state) { const c = committedPlans(state); return Object.keys(c).reduce(function (s, k) { return s + (validNumber(c[k].rate) ? c[k].rate : 0); }, 0); }
function hystDiffers(a, b) { return Math.abs(a - b) >= Math.max(SAVINGS_HYST_EUR, Math.abs(b) * SAVINGS_HYST_PCT / 100); }

/* Indirekter Bestand einer Aktie über die ETFs im Depot (€): Positionswert × Fondsgewicht. */
function indirectHoldingEur(recRows, nameKey) {
  const k = labelKey(nameKey);
  if (k.length < 4) return 0;
  let eur = 0;
  recRows.forEach(function (r) {
    if (isStock(r.etf) || !validNumber(r.value) || !r.etf.holdings) return;
    r.etf.holdings.forEach(function (h) {
      const hk = labelKey(h.name);
      if (hk && (hk.indexOf(k) === 0 || (" " + hk).indexOf(" " + k + " ") >= 0) && validNumber(h.weight)) eur += r.value * h.weight / 100;
    });
  });
  return eur;
}
function stockNameKey(name) {
  // erstes markantes Wort (≥ 4 Zeichen), z. B. „Allianz SE“ → „allianz“, „Münchener Rück“ → „munchener“
  const w = labelKey(name).split(" ").filter(function (x) { return x.length >= 4 && ["inc", "corp", "class", "aktie", "namens"].indexOf(x) < 0; });
  return w[0] || "";
}

function savingsPlan(state, recRows, sellRows, ideas, allowVirtual) {
  let saving = Math.max(0, Number(retirementSettings(state).saving) || 0);
  const virtual = !saving && !!allowVirtual;
  if (virtual) saving = 100;   // nur für Reihenfolge/Anteile, wenn keine Sparrate hinterlegt ist
  if (!saving) return null;
  const ri = retirementInfo(state);
  const horizon = Math.max(1, Math.min(12, ri ? Math.round(ri.years * 12) || 1 : 12));
  const sellPts = {};
  (sellRows || []).forEach(function (x) { if (x.etf) sellPts[x.etf.wkn] = x.pts; });
  const locked = {};
  state.positions.forEach(function (p) { if (p.lockDate) locked[p.wkn] = true; });
  const total = recTotalValue(recRows);   // inkl. 🏦 Tagesgeld — Sollanteile beziehen sich auf Depot + Tagesgeld
  const newIdeas = (ideas || []).filter(function (x) { return !x.tip && x.startPct; });
  /* Sollanteile neuer Ideen (ab v3.05) — Summe aller Ziele bleibt 100 %:
   *  · Kern/Reserve-Ideen füllen eine fehlende Stufe → Bestand wird um ihren Anteil gekürzt.
   *  · Satelliten-Ideen bekommen höchstens die Hälfte des FREIEN Satellitenplatzes (Soll − Ist) und
   *    nehmen ihn den bestehenden Satelliten ab (erst Satelliten, dann Kern) — der Kern bleibt beim Soll. */
  const isCR = function (x) { return x.c.tier === "core" || x.c.tier === "reserve"; };
  const crPct = Math.min(95, newIdeas.filter(isCR).reduce(function (s, x) { return s + x.startPct; }, 0));
  const scale = (100 - crPct) / 100;
  const items = [];
  recRows.forEach(function (r) {
    const wkn = r.etf.wkn;
    let skip = null;
    if (locked[wkn]) skip = "Mitarbeiteraktie (Sperrfrist) — nicht im Sparplan";
    else if ((sellPts[wkn] || 0) >= 3) skip = "Verkaufskandidat — keine Sparrate";
    else if (r.score === null) skip = "unvollständige Daten";
    items.push({ kind: "held", key: wkn, name: r.etf.name, value: r.value || 0, target: (r.targetShare || 0) * scale,
      tier: r.tierLabel, tierKey: r.tier || "satellite", score: r.score, skip: skip, share: r.share });
  });
  const heldOf = function (t) { return items.filter(function (it) { return it.tierKey === t; }); };
  const sumT = function (arr) { return arr.reduce(function (s, it) { return s + it.target; }, 0); };
  const hasCore = heldOf("core").length > 0 || newIdeas.some(function (x) { return x.c.tier === "core"; });
  const hasRes = !!recReserveCash(recRows) || heldOf("reserve").length > 0 || newIdeas.some(function (x) { return x.c.tier === "reserve"; });
  const satShareNow = recRows.reduce(function (s, r) { return s + ((r.tier || "satellite") === "satellite" && validNumber(r.share) ? r.share : 0); }, 0);
  const rfS = retirementF(state);
  const satBudget = hasCore
    ? (100 - (hasRes ? reservePct(state) : 0)) * (100 - (CORE_PCT[allocationProfile(state)] || 80)) / 100 * (1 - 0.5 * rfS)
    : sumT(heldOf("satellite"));
  // Ohne Kern ist das ganze Depot Satellit: neue Titel als Beimischung bis 30 % davon.
  const satRoom = hasCore ? Math.max(0, satBudget - satShareNow) / 2 : satBudget * 0.3;
  const satIdeas = newIdeas.filter(function (x) { return !isCR(x); });
  const satReq = satIdeas.reduce(function (s, x) { return s + x.startPct; }, 0);
  const satGive = Math.min(satReq, satRoom);
  const satF = satReq > 0 ? satGive / satReq : 0;
  // Den vergebenen Anteil den bestehenden Stufen abziehen (Satelliten, dann Kern, dann alle).
  let toTake = satGive;
  [heldOf("satellite"), heldOf("core"), items.slice()].forEach(function (grp) {
    const s = sumT(grp);
    if (toTake <= 1e-9 || s <= 1e-9) return;
    const take = Math.min(toTake, s);
    grp.forEach(function (it) { it.target -= take * it.target / s; });
    toTake -= take;
  });
  newIdeas.forEach(function (x) {
    const t = isCR(x) ? x.startPct : x.startPct * satF;
    items.push({ kind: "new", isin: x.c.isin, name: x.c.name, value: 0, target: t, tier: TIER_LABELS[x.c.tier || "satellite"],
      score: x.score, why: plainWhy(x.why[0]), idea: x,
      skip: t > 1e-9 ? null : "kein freier Platz im Satellitenanteil (Soll ≈ " + fmtR1(satBudget) + " %, Ist " + fmtR1(satShareNow) + " %)" });
  });
  // Depotbestand berücksichtigen
  recRows.forEach(function (r, idx) { items[idx].row = r; });
  items.forEach(function (it) {
    const isSt = it.kind === "held" ? isStock(it.row.etf) : (it.idea && it.idea.c.kind === "stock");
    it.indirect = isSt ? indirectHoldingEur(recRows, it.kind === "new" && it.idea.c.key ? it.idea.c.key : stockNameKey(it.name)) : 0;
    it.effValue = it.value + it.indirect;
  });
  // ETFs mit starker Überschneidung nur einmal besparen — der mit dem höheren Score.
  const heldEtfs = items.filter(function (it) { return it.kind === "held" && !it.skip && !isStock(it.row.etf) && it.row.etf.holdings && it.row.etf.holdings.length >= 5; });
  heldEtfs.forEach(function (a) {
    heldEtfs.forEach(function (b) {
      if (a === b || a.skip || b.skip) return;
      // Überschneidung relativ zum erfassten Fondsgewicht (robust, auch wenn nur Top-Positionen vorliegen).
      const cov = function (e) { return e.holdings.reduce(function (t, h) { return t + (validNumber(h.weight) ? h.weight : 0); }, 0); };
      const base = Math.min(cov(a.row.etf), cov(b.row.etf));
      const o = base > 0 ? Math.min(100, pairOverlap(a.row.etf, b.row.etf).weighted / base * 100) : 0;
      if (o < SAVINGS_OVERLAP_MAX) return;
      const loser = (a.score || 0) >= (b.score || 0) ? b : a, winner = loser === a ? b : a;
      loser.skip = "überschneidet sich zu " + fmtR1(o) + " % mit " + winner.name + " — Sparrate nur dort";
      winner.target += loser.target;   // Sollanteil des doppelten ETFs geht an den besparten
      winner.overlapValue = (winner.overlapValue || 0) + loser.value + (loser.overlapValue || 0);   // sein Bestand zählt mit
    });
  });
  const future = total + saving * horizon;
  items.forEach(function (it) {
    it.need = it.skip ? 0 : Math.max(0, it.target / 100 * future - it.effValue - (it.overlapValue || 0));
  });
  // Gewicht je Titel: 70 % nach Bedarf (Lücke zum Soll) + 30 % nach Sollgewicht (Basis:
  // den Kern stetig weiter besparen). Deutlich übergewichtete Titel (> 1,2× Soll) nur über Bedarf (= 0).
  items.forEach(function (it) {
    it.base = !it.skip && it.target > 0 && (it.kind === "new" || !validNumber(it.share) || it.share < it.target * 1.2) ? it.target : 0;
  });
  let active = items.filter(function (it) { return it.need > 0 || it.base > 0; })
    .sort(function (a, b) { return (b.need + b.base * future / 100) - (a.need + a.base * future / 100); }).slice(0, SAVINGS_MAX_PLANS);
  for (let round = 0; round < 10; round++) {
    const needSum = active.reduce(function (s, it) { return s + it.need; }, 0);
    const baseSum = active.reduce(function (s, it) { return s + it.base; }, 0);
    const wNeed = needSum > 0 ? (baseSum > 0 ? 0.7 : 1) : 0, wBase = 1 - wNeed;
    active.forEach(function (it) { it.raw = saving * ((needSum > 0 ? wNeed * it.need / needSum : 0) + (baseSum > 0 ? wBase * it.base / baseSum : 0)); });
    const tooSmall = active.filter(function (it) { return it.raw < SAVINGS_MIN_RATE; });
    if (!tooSmall.length || active.length === 1) break;
    tooSmall.sort(function (a, b) { return a.raw - b.raw; });
    active = active.filter(function (it) { return it !== tooSmall[0]; });
  }
  // Fallback: kein Bedarf (alles über Soll) → nach Sollgewicht verteilen.
  if (!active.length) {
    active = items.filter(function (it) { return !it.skip && it.target > 0; }).sort(function (a, b) { return b.target - a.target; }).slice(0, SAVINGS_MAX_PLANS);
    const tSum = active.reduce(function (s, it) { return s + it.target; }, 0) || 1;
    active.forEach(function (it) { it.raw = saving * it.target / tSum; });
  }
  // ISIN je Titel (für umgesetzte Sparpläne)
  items.forEach(function (it) { it.isinKey = String(it.kind === "held" ? displayIsin(state, it.key) : it.isin).toUpperCase(); });
  // Umgesetzte neue Titel, die gerade nicht (mehr) vorgeschlagen werden, weiter berücksichtigen
  Object.keys(committedPlans(state)).forEach(function (isin) {
    if (items.some(function (it) { return it.isinKey === isin; })) return;
    const cm = committedPlans(state)[isin];
    const it = { kind: "new", isin: isin, isinKey: isin, name: cm.name || isin, value: 0, target: 0, tier: "Satellit", score: null,
      why: "laufender Sparplan (nicht mehr unter den Vorschlägen)", skip: null, need: 0, raw: 0, idea: { c: { isin: isin, name: cm.name || isin, kind: cm.kind || "stock", tier: "satellite" } }, orphan: true };
    items.push(it);
  });
  // Runden auf 5 €, Rundungsrest auf den größten Posten.
  active.forEach(function (it) { it.rate = Math.max(saving < SAVINGS_MIN_RATE ? 0 : SAVINGS_STEP, Math.round(it.raw / SAVINGS_STEP) * SAVINGS_STEP); });
  if (saving < SAVINGS_MIN_RATE && active.length) { active = [active[0]]; active[0].rate = saving; }
  const diff = Math.round((saving - active.reduce(function (s, it) { return s + it.rate; }, 0)) * 100) / 100;
  if (active.length && diff) active.sort(function (a, b) { return b.rate - a.rate; })[0].rate += diff;
  // Stabilität: laufende Sparpläne behalten ihre Rate, solange der Vorschlag nur wenig abweicht;
  // die Differenz geht an nicht umgesetzte Titel (bzw. den größten Posten).
  if (!virtual) {
    let delta = 0;
    active.forEach(function (it) {
      const cm = commitOf(state, it.isinKey);
      it.proposed = it.rate;
      if (cm && !hystDiffers(it.rate, cm.rate)) { delta += it.rate - cm.rate; it.rate = cm.rate; it.kept = true; }
    });
    if (Math.abs(delta) > 0.001) {
      const free = active.filter(function (it) { return !it.kept; });
      const tgt = (free.length ? free : active).sort(function (a, b) { return b.rate - a.rate; })[0];
      if (tgt) tgt.rate = Math.max(0, Math.round((tgt.rate + delta) * 100) / 100);
    }
  }
  active.sort(function (a, b) { return b.rate - a.rate; });
  // Monatlicher Stichtag (v2.80): zwischen zwei Überprüfungen bleibt der Sparplan eingefroren.
  let snapshot = null;
  if (!virtual && !isAggregate(state)) {
    const snap = state.planSnapshot;
    const valid = snap && Array.isArray(snap.plans) && Date.now() < new Date(snap.nextAt).getTime() &&
      Math.abs((snap.saving || 0) - saving) < 0.01 && snap.profile === allocationProfile(state) &&
      snap.tierMode === "kpi";   // ab v3.08 Stufen aus Kennzahlen → älteren Stichtag einmal neu berechnen
    if (valid) {
      const byKey = {}; items.forEach(function (it) { byKey[it.isinKey] = it; });
      active = snap.plans.map(function (sp0) {
        let it = byKey[sp0.isin];
        if (!it) {   // Titel steht aktuell nicht mehr in der Berechnung — trotzdem bis zum Stichtag weiterführen
          it = { kind: sp0.kind === "held" ? "held" : "new", isin: sp0.isin, isinKey: sp0.isin, key: sp0.wkn || null, name: sp0.name, value: 0, target: sp0.target || 0,
            tier: sp0.tier || "Satellit", score: null, why: "aus dem Sparplan vom Stichtag", skip: null, need: 0,
            idea: { c: { isin: sp0.isin, name: sp0.name, kind: sp0.ckind || "stock", tier: "satellite" } }, frozenOnly: true, row: null };
          if (it.kind === "held") it.kind = "new";   // ohne aktuelle Zeile wie ein neuer Titel anzeigen
          items.push(it);
        }
        it.rate = sp0.rate; it.kept = !!sp0.kept;
        return it;
      });
      snapshot = snap;
    } else {
      const now = new Date();
      state.planSnapshot = {
        at: now.toISOString(),
        nextAt: new Date(now.getFullYear(), now.getMonth() + 1, 1).toISOString(),
        saving: saving, profile: allocationProfile(state), tierMode: "kpi",
        plans: active.map(function (it) {
          return { isin: it.isinKey, wkn: it.kind === "held" ? it.key : null, name: it.name, rate: it.rate, kind: it.kind,
            ckind: it.idea && it.idea.c ? it.idea.c.kind : null, tier: it.tier, target: it.target, kept: !!it.kept };
        }),
      };
      PLAN_SNAPSHOT_DIRTY = true;
      snapshot = state.planSnapshot;
    }
  }
  active.forEach(function (it) {
    it.pct = it.rate / saving * 100;
    it.after = total + saving * horizon > 0 ? (it.value + it.rate * horizon) / (total + saving * horizon) * 100 : null;
  });
  // Gründe für Titel ohne Rate + Index für Aufstocken/Kaufen
  items.forEach(function (it) {
    if (active.indexOf(it) >= 0 || it.skip) return;
    it.reason = it.need <= 0
      ? (it.indirect > 0 ? "inkl. indirekter Anteile über ETFs am bzw. über Sollgewicht" : "am bzw. über Sollgewicht")
      : "Lücke zu klein für eine Mindestrate von " + SAVINGS_MIN_RATE + " € bzw. nicht unter den " + SAVINGS_MAX_PLANS + " wichtigsten";
  });
  const index = {};
  items.forEach(function (it) {
    const rank = active.indexOf(it);
    index[it.kind === "held" ? "w:" + it.key : "i:" + it.isin] = { rate: rank >= 0 ? it.rate : 0, pct: rank >= 0 ? it.pct : 0, rank: rank >= 0 ? rank + 1 : null,
      reason: it.skip || it.reason || null, need: it.need, item: it };
  });
  return { saving: saving, virtual: virtual, horizon: horizon, total: total, plans: active, index: index, items: items, snapshot: snapshot,
    skipped: items.filter(function (it) { return it.skip; }),
    without: items.filter(function (it) { return !it.skip && active.indexOf(it) < 0 && (it.kind === "held" || it.orphan); }) };
}

let PLAN_STATE = null;   // für planBadge
let PLAN_SNAPSHOT_DIRTY = false;   // neuer Monats-Stand berechnet → nach dem Seitenaufbau speichern
/* Kurztext „im Sparplan“ für Karten. */
function planBadge(plan, key) {
  if (!plan) return "";
  const x = plan.index[key];
  if (!x) return "";
  const cmI = x.item && x.item.isinKey && PLAN_STATE ? commitOf(PLAN_STATE, x.item.isinKey) : null;
  if (cmI) return '<div class="planBadge on">✅ Sparplan läuft: ' + esc(fmtEur(cmI.rate)) + '/Monat seit ' + new Date(cmI.since).toLocaleDateString("de-DE") +
    (x.rate > 0 && hystDiffers(x.rate, cmI.rate) ? ' · Vorschlag jetzt ' + esc(fmtEur(x.rate)) : (x.rate > 0 ? '' : ' · Vorschlag: pausieren')) + '</div>';
  const amt = plan.virtual ? fmtR1(x.pct) + " % der Zukäufe" : fmtEur(x.rate) + "/Monat";
  return x.rate > 0
    ? '<div class="planBadge on">💰 Im Sparplan #' + x.rank + ': ' + esc(amt) + (x.need > 0 ? ' · Lücke bis Soll ≈ ' + esc(fmtEur(x.need)) : '') + '</div>'
    : '<div class="planBadge">⏸ Nicht im Sparplan: ' + esc(x.reason || "kein Bedarf") + '</div>';
}
function planNoteHtml(plan) {
  if (!plan) return "";
  return plan.virtual
    ? "<div class='pageWarn'>💰 Keine Sparrate hinterlegt — Reihenfolge und Anteile rechnen mit 100 € (⚙️ → Sollgewichtung → „💰 Monatliche Sparrate“). Aufstocken, Kaufen und Sparplan nutzen dieselbe Berechnung.</div>"
    : "<p class='caption'>Abgestimmt mit dem Sparplan (" + fmtEur(plan.saving) + "/Monat): gleiche Reihenfolge und Ausschlüsse in Aufstocken, Kaufen und Sparplan.</p>";
}


/* Zeigt den EINEN Sparplan, den recommendationPageHtml() auch für Aufstocken, Kaufen und
 * Zusammenfassung berechnet hat — keine zweite Berechnung, damit alle Bereiche übereinstimmen.
 * Ein „virtueller“ Plan (keine Sparrate hinterlegt) wird hier nicht als Vorschlag gezeigt. */
function savingsPlanHtml(state, plan) {
  const sp = plan && !plan.virtual ? plan : null;
  if (!plan && (Number(retirementSettings(state).saving) || 0) > 0) return "<p class='hint'>Sparplan nicht berechenbar (Details im Fehlerlog).</p>";
  if (!sp) return "<p class='hint'>Keine Sparrate hinterlegt — unter ⚙️ → Sollgewichtung → „💰 Monatliche Sparrate“ eintragen.</p>";
  const head = '<div class="sumBox"><b>Sparplan-Vorschlag</b><p style="font-size:28px;font-weight:700;margin:6px 0 2px">' + fmtEur(sp.saving) + ' <span style="font-size:15px;font-weight:400;color:var(--dim)">pro Monat</span></p>' +
    (Object.keys(committedPlans(state)).length ? '<small>✅ umgesetzt: ' + Object.keys(committedPlans(state)).length + ' Sparpläne, ' + fmtEur(committedTotal(state)) + '/Monat' +
      (Math.abs(committedTotal(state) - sp.saving) >= 1 ? ' (Sparrate ' + fmtEur(sp.saving) + ')' : '') + '</small><br>' : '') +
    (sp.snapshot ? '<small>📅 Stand ' + new Date(sp.snapshot.at).toLocaleDateString("de-DE") + ' · nächste Überprüfung ' + new Date(sp.snapshot.nextAt).toLocaleDateString("de-DE") +
      ' — bis dahin bleibt der Vorschlag unverändert</small><br>' : '') +
    '<small>' + sp.plans.length + ' Sparpläne · Ziel: Sollgewicht in ' + sp.horizon + ' Monaten' + (buyIdeasOn(state) ? ' · inkl. empfohlener neuer Titel' : ' · neue Kaufideen sind aus (⚙️)') + '</small></div>';
  const rows = sp.plans.map(function (it) {
    const ids = (it.kind === "held" ? idsHtml(state, it.key) : "") + isinChip(it.kind === "held" ? displayIsin(state, it.key) : it.isin);
    const why = it.kind === "held"
      ? "bestehend · " + it.tier + " · Gewicht " + (validNumber(it.share) ? fmtR1(it.share) : "–") + " % → Soll " + fmtR1(it.target) + " %" + (validNumber(it.after) ? " (in " + sp.horizon + " M ≈ " + fmtR1(it.after) + " %)" : "")
      : "🆕 neu anlegen · " + it.tier + " · 🏭 " + buyIdeaBranche(state, it.idea.c).label + " · Soll " + fmtR1(it.target) + " % · " + it.why;
    const stock = holdingLine(it);
    const cm = commitOf(state, it.isinKey);
    const commitHref = "scriptable:plan-commit?isin=" + encodeURIComponent(it.isinKey) + "&rate=" + it.rate + "&name=" + encodeURIComponent(it.name) +
      "&kind=" + (it.kind === "held" && it.row ? (isStock(it.row.etf) ? "stock" : "etf") : ((it.idea && it.idea.c.kind) || "stock")) + (it.kind === "held" ? "&wkn=" + encodeURIComponent(it.key) : "");
    const commitLine = cm
      ? '<a class="commitChip on" href="' + commitHref + '">✅ läuft seit ' + new Date(cm.since).toLocaleDateString("de-DE") + ' · ' + fmtEur(cm.rate) + '/Monat</a>' +
        (hystDiffers(it.rate, cm.rate) ? '<span class="commitHint">↔ Vorschlag jetzt ' + fmtEur(it.rate) + ' — Sparplan anpassen</span>' : '<span class="commitHint">passt</span>')
      : '<a class="commitChip" href="' + commitHref + '">☐ als umgesetzt abhaken</a>';
    return '<div class="sumItem"><div class="sumHead"><span>' + (cm ? "✅" : (it.kind === "new" ? "🆕" : "🔁")) + ' <b>' + esc(it.name) + '</b></span><span class="sumAmt">' + fmtEur(it.rate) + '</span></div>' +
      (sp.virtual ? '' : '<div class="sumWhy">' + commitLine + '</div>') +
      '<div class="sumWhy">' + ids + '</div>' +
      '<div class="sumWhy">' + esc(why) + ' · ' + fmtR1(it.pct) + ' % der Sparrate</div>' +
      (stock ? '<div class="sumWhy">📦 ' + esc(stock) + '</div>' : '') + '</div>';
  }).join("");
  function holdingLine(it) {
    const pct = function (v) { return sp.total > 0 ? " (" + fmtR1(v / sp.total * 100) + " %)" : ""; };
    const parts = [];
    if (it.kind === "held") parts.push("im Depot direkt " + fmtEur(it.value) + pct(it.value));
    else parts.push(it.indirect > 0 ? "noch keine eigene Position" : "noch nicht im Depot");
    if (it.indirect > 0) parts.push("indirekt über ETFs ≈ " + fmtEur(it.indirect) + pct(it.indirect) + " — bei der Rate berücksichtigt");
    if (it.overlapValue) parts.push("plus überschneidender ETF ≈ " + fmtEur(it.overlapValue) + " (pausiert)");
    return parts.join(" · ");
  }
  const off = sp.skipped.concat(sp.without).map(function (it) {
    const cmo = commitOf(state, it.isinKey || displayIsin(state, it.key));
    return '<div class="sumItem"><div class="sumHead"><span>⏸ <b>' + esc(it.name) + '</b></span><span class="sumAmt">0 €</span></div>' +
      (cmo ? '<div class="sumWhy"><a class="commitChip on" href="scriptable:plan-commit?isin=' + encodeURIComponent(String(it.isinKey || displayIsin(state, it.key)).toUpperCase()) + '&rate=0&name=' + encodeURIComponent(it.name) + '">✅ läuft mit ' + fmtEur(cmo.rate) + '/Monat — Sparplan pausieren empfohlen</a></div>' : '') +
      '<div class="sumWhy">' + esc(it.orphan ? "nicht mehr unter den Vorschlägen" : it.skip || ((it.indirect > 0 ? "inkl. indirekter Anteile über ETFs (≈ " + fmtEur(it.indirect) + ") am bzw. über Sollgewicht" : "über bzw. am Sollgewicht") + " — Sparplan pausieren oder auslaufen lassen")) + '</div>' +
      '<div class="sumWhy">📦 im Depot ' + fmtEur(it.value) + (sp.total > 0 ? " (" + fmtR1(it.value / sp.total * 100) + " %)" : "") + '</div></div>';
  }).join("");
  const text = sp.plans.map(function (it) {
    const isin = it.kind === "held" ? displayIsin(state, it.key) : it.isin;
    const cm = commitOf(state, isin);
    return (cm ? (hystDiffers(it.rate, cm.rate) ? "ÄND  " : "OK   ") : (it.kind === "new" ? "NEU  " : "     ")) + fmtEur(it.rate).padStart(10) + "  " + it.name + "  (" + isin + ")";
  }).join("\n") + "\n" + "Summe " + fmtEur(sp.saving) + " / Monat";
  return head +
    (sp.snapshot ? '<div class="refreshBar"><a class="refreshBtn" href="scriptable:plan-recalc">↻ Sparplan jetzt neu berechnen</a>' +
      '<span>sonst automatisch zum ' + new Date(sp.snapshot.nextAt).toLocaleDateString("de-DE") + '</span></div>' : '') +
    '<h3 class="miniHead">Sparpläne anlegen / anpassen</h3><div class="iosGroup">' + rows + '</div>' +
    (off ? '<h3 class="miniHead">Ohne Sparrate</h3><div class="iosGroup">' + off + '</div>' : '') +
    '<h3 class="miniHead">Liste zum Kopieren</h3>' +
    '<textarea readonly onclick="this.select()" style="width:100%;min-height:' + (sp.plans.length * 20 + 40) + 'px;font-size:13px;line-height:1.5;border-radius:16px;padding:12px;border:.5px solid var(--glass-brd,var(--line));background:var(--glass,var(--card));color:var(--ink)">' + esc(text) + '</textarea>' +
    "<p class='foot'>Bestand zählt inkl. indirekter Aktienanteile über ETFs (Durchschau); ETFs mit ≥ " + SAVINGS_OVERLAP_MAX + " % Überschneidung werden nur einmal bespart. Verteilung zu 70 % nach Abstand zum Sollgewicht in " + sp.horizon + " Monaten und zu 30 % nach Sollgewicht (Kern/Satellit/Reserve" + (retirementInfo(state) ? ", Ruhestand" : "") + "). Mindestrate " + SAVINGS_MIN_RATE + " € je Sparplan, auf " + SAVINGS_STEP + " € gerundet, höchstens " + SAVINGS_MAX_PLANS + " Sparpläne. Sparplanfähigkeit und Ausführungstermine bei comdirect prüfen; neue Titel: Kurs, Dividende und Kosten im Bereich „💡 Kaufen“. Keine Anlageberatung.</p>";
}

